use clap::{Parser, ArgGroup, ValueParser};
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fs;
use std::io::{self, Read};
use unicode_segmentation::UnicodeSegmentation;

#[derive(Parser, Debug)]
#[command(name = "grex")]
#[command(version = "1.4.6")]
#[command(author = "© 2019-today Peter M. Stahl <pemistahl@gmail.com>")]
#[command(about = "grex generates regular expressions from user-provided test cases.", long_about = None)]
#[command(override_usage = "grex [OPTIONS] {INPUT...|--file <FILE>}")]
#[command(disable_help_flag = true)]
#[command(disable_version_flag = true)]
struct Cli {
    #[arg(value_name = "INPUT", help = "One or more test cases separated by blank space", long_help = "One or more test cases separated by blank space\n\nUse a hyphen `-` to read test cases from standard input.\n\nConflicts with --file.")]
    input: Vec<String>,

    #[arg(short = 'f', long = "file", value_name = "FILE", help = "Reads test cases on separate lines from a file", long_help = "Reads test cases on separate lines from a file.\n\nLines may be ended with either a newline `\\n` or a carriage return with a line feed `\\r\\n`. The final line ending is optional.\n\nUse a hyphen `-` to read the filename from standard input.\n\nConflicts with INPUT...")]
    file: Option<String>,

    #[arg(short = 'd', long = "digits", help = "Converts any Unicode decimal digit to \\d", long_help = "Converts any Unicode decimal digit to \\d.\n\nTakes precedence over --words if both are set. Decimal digits are converted to \\d, remaining word characters to \\w.\n\nTakes precedence over --non-spaces if both are set. Decimal digits are converted to \\d, remaining non-space characters to \\S.")]
    digits: bool,

    #[arg(short = 'D', long = "non-digits", help = "Converts any character which is not a Unicode decimal digit to \\D", long_help = "Converts any character which is not a Unicode decimal digit to \\D.\n\nTakes precedence over --non-words if both are set. Non-digits which are also non-word characters are converted to \\D.\n\nTakes precedence over --non-spaces if both are set. Non-digits which are also non-space characters are converted to \\D.")]
    non_digits: bool,

    #[arg(short = 's', long = "spaces", help = "Converts any Unicode whitespace character to \\s", long_help = "Converts any Unicode whitespace character to \\s.\n\nTakes precedence over --non-digits if both are set. Whitespace is converted to \\s, remaining non-digits to \\D.\n\nTakes precedence over --non-words if both are set. Whitespace is converted to \\s, remaining non-word characters to \\W.")]
    spaces: bool,

    #[arg(short = 'S', long = "non-spaces", help = "Converts any character which is not a Unicode whitespace character to \\S")]
    non_spaces: bool,

    #[arg(short = 'w', long = "words", help = "Converts any Unicode word character to \\w", long_help = "Converts any Unicode word character to \\w.\n\nTakes precedence over --non-digits if both are set. Word characters are converted to \\w, remaining non-digits to \\D.\n\nTakes precedence over --non-spaces if both are set. Word characters are converted to \\w, remaining non-whitespace to \\S.")]
    words: bool,

    #[arg(short = 'W', long = "non-words", help = "Converts any character which is not a Unicode word character to \\W", long_help = "Converts any character which is not a Unicode word character to \\W.\n\nTakes precedence over --non-spaces if both are set. Non-word characters which are also non-whitespace are converted to \\W.")]
    non_words: bool,

    #[arg(short = 'e', long = "escape", help = "Replaces all non-ASCII characters with unicode escape sequences")]
    escape: bool,

    #[arg(long = "with-surrogates", help = "Converts astral code points to surrogate pairs if --escape is set")]
    with_surrogates: bool,

    #[arg(short = 'r', long = "repetitions", help = "Detects repeated non-overlapping substrings and converts them to {min,max} quantifier notation")]
    repetitions: bool,

    #[arg(long = "min-repetitions", value_name = "QUANTITY", default_value = "1", help = "Specifies the minimum quantity of substring repetitions to be converted if --repetitions is set", long_help = "Specifies the minimum quantity of substring repetitions to be converted if --repetitions is set\n\n[default: 1]", value_parser = parse_non_zero)]
    min_repetitions: u32,

    #[arg(long = "min-substring-length", value_name = "LENGTH", default_value = "1", help = "Specifies the minimum length a repeated substring must have in order to be converted if --repetitions is set", long_help = "Specifies the minimum length a repeated substring must have in order to be converted if --repetitions is set\n\n[default: 1]", value_parser = parse_non_zero)]
    min_substring_length: u32,

    #[arg(long = "no-start-anchor", help = "Removes the caret anchor `^` from the resulting regular expression", long_help = "Removes the caret anchor `^` from the resulting regular expression.\n\nBy default, the caret anchor is added to every generated regular expression which guarantees that the expression matches the test cases given as input only at the start of a string.\n\nThis flag removes the anchor, thereby allowing to match the test cases also when they do not occur at the start of a string.")]
    no_start_anchor: bool,

    #[arg(long = "no-end-anchor", help = "Removes the dollar sign anchor `$` from the resulting regular expression", long_help = "Removes the dollar sign anchor `$` from the resulting regular expression.\n\nBy default, the dollar sign anchor is added to every generated regular expression which guarantees that the expression matches the test cases given as input only at the end of a string.\n\nThis flag removes the anchor, thereby allowing to match the test cases also when they do not occur at the end of a string.")]
    no_end_anchor: bool,

    #[arg(long = "no-anchors", help = "Removes the caret and dollar sign anchors from the resulting regular expression", long_help = "Removes the caret and dollar sign anchors from the resulting regular expression.\n\nBy default, anchors are added to every generated regular expression which guarantees that the expression exactly matches only the test cases given as input and nothing else.\n\nThis flag removes the anchors, thereby allowing to match the test cases also when they occur within a larger string that contains other content as well.")]
    no_anchors: bool,

    #[arg(short = 'x', long = "verbose", help = "Produces a nicer-looking regular expression in verbose mode")]
    verbose: bool,

    #[arg(short = 'c', long = "colorize", help = "Provides syntax highlighting for the resulting regular expression")]
    colorize: bool,

    #[arg(short = 'i', long = "ignore-case", help = "Performs case-insensitive matching, letters match both upper and lower case")]
    ignore_case: bool,

    #[arg(short = 'g', long = "capture-groups", help = "Replaces non-capturing groups with capturing ones")]
    capture_groups: bool,

    #[arg(short = 'h', long = "help", help = "Prints help information")]
    help: bool,

    #[arg(short = 'v', long = "version", help = "Prints version information")]
    version: bool,
}

fn parse_non_zero(s: &str) -> Result<u32, String> {
    match s.parse::<i64>() {
        Ok(v) => {
            if v == 0 {
                Err(format!("Value must not be zero"))
            } else if v < 0 {
                Err(format!("Value is not a valid unsigned integer"))
            } else if v > u32::MAX as i64 {
                Err(format!("Value is not a valid unsigned integer"))
            } else {
                Ok(v as u32)
            }
        }
        Err(_) => {
            // check if negative?
            if s.starts_with('-') {
                Err(format!("Value is not a valid unsigned integer"))
            } else {
                Err(format!("Value is not a valid unsigned integer"))
            }
        }
    }
}

fn main() {
    let mut args: Vec<String> = std::env::args().collect();
    // Custom handling to replicate clap behavior for help/version and error messages
    // We will use clap but need to handle conflicts manually to match original messages.

    // First, handle --help and -h and --version -v manually for precedence similar to original?
    // Original prints help even if inputs present.
    let has_help = args.iter().any(|a| a == "--help" || a == "-h");
    let has_version = args.iter().any(|a| a == "--version" || a == "-v");

    if has_help {
        // Print help - need to distinguish -h vs --help for short vs long?
        // If any --help present, print long help, else if -h present print short.
        // Check if --help present -> long, else short.
        if args.iter().any(|a| a == "--help") {
            print_long_help();
        } else {
            print_short_help();
        }
        return;
    }
    if has_version {
        println!("grex 1.4.6");
        return;
    }

    // Now parse with clap, but we want to handle errors to match original messages.
    // We'll attempt to parse using Cli::try_parse, but we need to handle conflicts for file vs input.
    // Original behavior:
    // - file cannot be used multiple times -> error: the argument '--file <FILE>' cannot be used multiple times
    // - file cannot be used with INPUT... -> error: the argument '--file <FILE>' cannot be used with '[INPUT]...'
    // These are clap's default conflict messages.

    // For our implementation, we'll manually check some errors to match.

    // Check for unknown flags that look like -? Actually original treats unknown flags as inputs, not errors. For example, -z is treated as input. So we should allow hyphen values.

    // Clap's default: unknown args starting with - should be error, but original allows them as inputs if they are not defined? Wait earlier we saw ./executable -z gave ^\-z$ as output, not error. So -z is treated as input, not error.
    // Similarly --unknown gave ^\-\-unknown$ . So unknown options are treated as inputs!

    // That means original's CLI is configured to allow hyphen values and not error on unknown.

    // We saw ./executable --unknown-flag gave output, not error.
    // But ./executable --min-repetitions abc gave error about invalid value. So it does validate known options.

    // So original allows unknown long options? That is weird, but we observed --unknown => treated as input.
    // How to replicate with clap? We need allow_hyphen_values and allow_external_subcommands? Actually we need to configure that unknown args are allowed as positional values?
    // In clap, to allow "-" as value, you need allow_hyphen_values.

    // But for --unknown, clap would normally error unknown argument. But original doesn't error, so it must have disabled that? Perhaps they use Arg::allow_hyphen_values and also not have strict unknown check? Or they use trailing_var_arg?

    // Let's test: ./executable --unknown -> treated as input. So clap is set to allow any hyphen value as positional, not error.

    // In clap 4, you can set arg with allow_hyphen_values true, and also set command to allow_external_subcommands? Hmm.

    // Simpler: we will manually parse args without clap to replicate this permissive behavior, but still need to produce same error messages for known args with missing values or invalid values.

    // Approach: Manual parsing:
    // - Iterate over args[1..].
    // - If we encounter "--" then rest are inputs (positional) as literal (including those that look like flags).
    // - If we encounter known flags (like -d, --digits, -f, --file, etc.), handle them.
    // - For -f/--file, it takes a value. If value missing, error.
    // - For --min-repetitions and --min-substring-length, takes value, must be non-zero unsigned.
    // - For unknown flags starting with "-", treat as input? But we need to distinguish between unknown flag and known flag's value? For known flags that require value, if next arg is missing, error. If next arg is something like "-"? Could be value? For -f -, "-" is a valid file value meaning read filename from stdin. So "-" can be value for file.

    // - For flags that are boolean (no value), if unknown, treat as input.

    // Let's implement manual parser that matches observed error messages.

    let mut file: Option<String> = None;
    let mut digits = false;
    let mut non_digits = false;
    let mut spaces = false;
    let mut non_spaces = false;
    let mut words = false;
    let mut non_words = false;
    let mut escape = false;
    let mut with_surrogates = false;
    let mut repetitions = false;
    let mut min_repetitions: u32 = 1;
    let mut min_substring_length: u32 = 1;
    let mut no_start_anchor = false;
    let mut no_end_anchor = false;
    let mut no_anchors = false;
    let mut verbose = false;
    let mut colorize = false;
    let mut ignore_case = false;
    let mut capture_groups = false;
    let mut inputs: Vec<String> = Vec::new();

    let mut i = 1;
    let mut after_double_dash = false;
    let mut file_seen = false;
    let mut min_rep_seen = false;
    let mut min_sub_len_seen = false;

    while i < args.len() {
        let arg = args[i].clone();
        if after_double_dash {
            inputs.push(arg);
            i += 1;
            continue;
        }
        if arg == "--" {
            after_double_dash = true;
            i += 1;
            continue;
        }
        // Handle known boolean flags
        match arg.as_str() {
            "-d" | "--digits" => {
                digits = true;
                i += 1;
                continue;
            }
            "-D" | "--non-digits" => {
                non_digits = true;
                i += 1;
                continue;
            }
            "-s" | "--spaces" => {
                spaces = true;
                i += 1;
                continue;
            }
            "-S" | "--non-spaces" => {
                non_spaces = true;
                i += 1;
                continue;
            }
            "-w" | "--words" => {
                words = true;
                i += 1;
                continue;
            }
            "-W" | "--non-words" => {
                non_words = true;
                i += 1;
                continue;
            }
            "-e" | "--escape" => {
                escape = true;
                i += 1;
                continue;
            }
            "--with-surrogates" => {
                with_surrogates = true;
                i += 1;
                continue;
            }
            "-r" | "--repetitions" => {
                repetitions = true;
                i += 1;
                continue;
            }
            "--no-start-anchor" => {
                no_start_anchor = true;
                i += 1;
                continue;
            }
            "--no-end-anchor" => {
                no_end_anchor = true;
                i += 1;
                continue;
            }
            "--no-anchors" => {
                no_anchors = true;
                i += 1;
                continue;
            }
            "-x" | "--verbose" => {
                verbose = true;
                i += 1;
                continue;
            }
            "-c" | "--colorize" => {
                colorize = true;
                i += 1;
                continue;
            }
            "-i" | "--ignore-case" => {
                ignore_case = true;
                i += 1;
                continue;
            }
            "-g" | "--capture-groups" => {
                capture_groups = true;
                i += 1;
                continue;
            }
            "-h" | "--help" | "-v" | "--version" => {
                // Should have been handled earlier, but if we reach here due to after --, treat as input
                // Actually if before --, we already handled help/version globally. So here it's after --, so input.
                inputs.push(arg);
                i += 1;
                continue;
            }
            _ => {}
        }

        // Handle options with values
        if arg == "-f" || arg == "--file" {
            if file_seen {
                eprintln!("error: the argument '--file <FILE>' cannot be used multiple times\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            file_seen = true;
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            let val = args[i+1].clone();
            file = Some(val);
            i += 2;
            continue;
        }
        if arg.starts_with("--file=") {
            if file_seen {
                eprintln!("error: the argument '--file <FILE>' cannot be used multiple times\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            file_seen = true;
            let val = arg["--file=".len()..].to_string();
            if val.is_empty() {
                eprintln!("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            file = Some(val);
            i += 1;
            continue;
        }
        if arg == "--min-repetitions" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--min-repetitions <QUANTITY>' but none was supplied\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            let val_str = args[i+1].clone();
            match parse_non_zero_cloned(&val_str) {
                Ok(v) => {
                    min_repetitions = v;
                }
                Err(e) => {
                    if e == "zero" {
                        eprintln!("error: invalid value '0' for '--min-repetitions <QUANTITY>': Value must not be zero\n\nFor more information, try '--help'.");
                    } else {
                        eprintln!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", val_str);
                    }
                    std::process::exit(2);
                }
            }
            i += 2;
            continue;
        }
        if arg.starts_with("--min-repetitions=") {
            let val_str = arg["--min-repetitions=".len()..].to_string();
            if val_str.is_empty() {
                eprintln!("error: a value is required for '--min-repetitions <QUANTITY>' but none was supplied\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            match parse_non_zero_cloned(&val_str) {
                Ok(v) => min_repetitions = v,
                Err(e) => {
                    if e == "zero" {
                        eprintln!("error: invalid value '0' for '--min-repetitions <QUANTITY>': Value must not be zero\n\nFor more information, try '--help'.");
                    } else {
                        eprintln!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", val_str);
                    }
                    std::process::exit(2);
                }
            }
            i += 1;
            continue;
        }
        if arg == "--min-substring-length" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--min-substring-length <LENGTH>' but none was supplied\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
