fn convert_repetition_single(s: &str, min_sub_len: u32, min_rep: u32) -> String {
    // Greedy left-to-right using find_repetition for whole remaining?
    // We'll attempt iterative: result parts, i=0
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i = 0;
    while i < n {
        let remaining: String = chars[i..].iter().collect();
        if let Some((start, l, count)) = find_repetition(&remaining, min_sub_len, min_rep) {
            // start is relative to remaining
            if start > 0 {
                // emit literal prefix of length start
                let prefix: String = chars[i..i+start].iter().collect();
                // Escape prefix literal
                result.push_str(&escape_literal(&prefix));
                i += start;
                continue;
            } else {
                // start==0, we have repetition at current position
                let sub: String = chars[i..i+l].iter().collect();
                let esc_sub = escape_literal(&sub);
                // Build quantifier
                if l == 1 {
                    // Single char repetition
                    // Need to handle if esc_sub is like \d etc? But for repetition conversion of raw string, we haven't applied char class conversions yet.
                    // For "a" repetition, we want "a{count}"
                    result.push_str(&format!("{}{{{}}}", esc_sub, count));
                } else {
                    result.push_str(&format!("(?:{}){{{}}}", esc_sub, count));
                }
                i += l * count;
                continue;
            }
        } else {
            // No repetition found, emit single char
            let c = chars[i];
            // Escape
            if ".^$*+?()[]{}|\\".contains(c) {
                result.push('\\');
                result.push(c);
            } else {
                result.push(c);
            }
            i += 1;
        }
    }
    result
}

