#[derive(Debug)]
struct Node {
    children: BTreeMap<String, Node>,
    is_end: bool,
}

impl Node {
    fn new() -> Self {
        Node {
            children: BTreeMap::new(),
            is_end: false,
        }
    }

    fn insert(&mut self, graphemes: &[String]) {
        if graphemes.is_empty() {
            self.is_end = true;
            return;
        }
        let first = graphemes[0].clone();
        let child = self.children.entry(first).or_insert_with(Node::new);
        child.insert(&graphemes[1..]);
    }
}

fn is_digit(s: &str) -> bool {
    // Unicode decimal digit: Nd category?
    // Use char property: check if char is decimal digit via Unicode.
    // For simplicity, check if s is single char and is digit via char::is_ascii_digit or unicode?
    // We need Unicode decimal digit: includes e.g., \u0660 etc.
    // We can use s.chars().all(|c| c.is_ascii_digit() || is_unicode_digit(c))? Let's check Unicode Nd.
    // For grapheme that is single codepoint, check if it's Nd.
    // For multi-codepoint grapheme, probably not digit.
    if s.chars().count() != 1 {
        return false;
    }
    let c = s.chars().next().unwrap();
    // Use unicode property: is digit
    // In Rust, char::is_digit with radix? But that checks numeric? We want decimal digit.
    // We can approximate: check if c.is_digit(10) but that includes many? Actually is_digit(10) checks decimal digit.
    // Let's use: c.is_ascii_digit() || (c as u32 >= 0x0660 && c as u32 <= 0x0669 etc) not complete.
    // Better: use c.is_digit(10) but that should cover Unicode decimal digits.
    // According to Rust docs, is_digit(10) checks Nd.
    c.is_digit(10)
}

fn is_space(s: &str) -> bool {
    if s.chars().count() != 1 {
        return false;
    }
    let c = s.chars().next().unwrap();
    // Unicode whitespace: use is_whitespace
    c.is_whitespace()
}

fn is_word(s: &str) -> bool {
    if s.chars().count() != 1 {
        // For multi-codepoint grapheme like y + combining, is it word? In grex, y with combining appears as word when -w is set: it becomes \w\w (two \w?). Actually earlier we saw -w with y combining gave \w\w, so each codepoint? The grapheme y+combining is two codepoints, but it gave two \w? Let's see: y combining with -w gave \w\w . That's two \w for one grapheme cluster of two codepoints. So for conversion, they treat each codepoint? Or each grapheme's codepoints as separate? For "y\u0306", grapheme cluster is y + combining, with -w it gave \w\w (two). So they convert each codepoint inside grapheme separately.
        // So for our conversion, we should work on codepoints, not graphemes, for -w etc.

        // For simplicity, if multi-codepoint grapheme, we will check if all codepoints are word? If any is word, treat as word?
        // But observed \w\w for y+combining suggests each codepoint converted individually to \w.
        // So is_word for grapheme cluster should be true if any codepoint is word? Actually both y and combining breve? Combining breve is not word? But they gave \w\w, so combining breve considered word? Let's check.
        // Might be that word detection is per codepoint, and conversion happens per codepoint, so multi-codepoint grapheme becomes multiple \w.

        // For our is_word for single codepoint, we need to check Unicode word: alphanumeric + underscore? In Rust, regex \w is [A-Za-z0-9_]. But grex says Unicode word character.
        // Let's approximate: word character if alphanumeric or underscore.

        return s.chars().all(|c| is_word_char(c));
    }
