}

fn is_word_char(c: char) -> bool {
    // Unicode word: includes letters, digits, underscore? According to Unicode, \w is \p{Alphabetic} + \p{M} + \p{Nd} + \p{Pc} ?
    // For simplicity: if alphanumeric or '_' or maybe other?
    // We'll use: c.is_alphanumeric() || c == '_'
    c.is_alphanumeric() || c == '_'
}

fn is_digit_char(c: char) -> bool {
    c.is_digit(10)
}

fn is_space_char(c: char) -> bool {
    c.is_whitespace()
}

fn escape_literal_graphemes(gs: &[String]) -> String {
    let mut res = String::new();
    for g in gs {
        // g is a grapheme cluster
        // For escaping, we need to escape each codepoint that is regex special?
        // For simplicity, if grapheme is single codepoint and special, escape.
        if g.chars().count() == 1 {
            let c = g.chars().next().unwrap();
            if ".^$*+?()[]{}|\\".contains(c) {
                res.push('\\');
                res.push(c);
            } else {
                res.push_str(g);
            }
        } else {
            // multi-codepoint grapheme: keep as is (e.g., y + combining)
            res.push_str(g);
        }
    }
    res
}

fn escape_inside_class_single(c: char) -> String {
    if "\\-]^[\"".contains(c) {
        // Actually need to escape \ ] ^ - [ 
        // We handle [ as \]? For inside class, [ needs escaping as \[
        if c == '[' || c == ']' || c == '\\' || c == '^' || c == '-' {
            return format!("\\{}", c);
        }
    }
    c.to_string()
}

fn build_char_class(chars: &[String]) -> (Option<String>, Vec<String>) {
    // chars are single graphemes (first chars) that share same suffix
    let mut single: Vec<char> = Vec::new();
    let mut multi: Vec<String> = Vec::new();
    for ch in chars {
        let gc = ch;
        if gc.chars().count() == 1 {
            single.push(gc.chars().next().unwrap());
        } else {
            multi.push(gc.clone());
        }
    }
    if single.is_empty() {
        return (None, multi);
    }
    // dedup and sort
    let mut set: BTreeSet<char> = BTreeSet::new();
    for c in single {
        set.insert(c);
    }
    let sorted: Vec<char> = set.into_iter().collect();
    // find runs
    let mut runs: Vec<Vec<char>> = Vec::new();
    let mut cur: Vec<char> = Vec::new();
    for &c in &sorted {
        if cur.is_empty() {
            cur.push(c);
        } else {
            if c as u32 == cur.last().unwrap().clone() as u32 + 1 {
                cur.push(c);
            } else {
                runs.push(cur);
                cur = vec![c];
            }
        }
    }
    if !cur.is_empty() {
        runs.push(cur);
    }
    let mut content = String::new();
    for run in runs {
        if run.len() >= 3 {
            let first = run[0];
            let last = run[run.len() - 1];
            content.push_str(&escape_inside_class_single(first));
            content.push('-');
            content.push_str(&escape_inside_class_single(last));
        } else {
            for c in run {
                content.push_str(&escape_inside_class_single(c));
            }
        }
    }
    (Some(format!("[{}]", content)), multi)
}

fn is_simple_regex(s: &str) -> bool {
    // simple if single char or char class without | and without grouping that needs wrapping
    // For optional handling
    if s.len() == 1 {
        return true;
    }
    if s.starts_with('[') && s.ends_with(']') && !s.contains('|') {
        return true;
    }
    // If it's like \d, \w, \s, etc (two chars)
    if s.starts_with('\\') && s.len() == 2 {
        return true;
    }
    // If it's like \u{...} maybe longer but still simple? For escaping non-ascii, it's \u{hex}
    if s.starts_with("\\u{") && s.ends_with('}') {
        return true;
    }
    // If it's surrogate pair like \u{d83d}\u{de00} -> contains two escapes, not simple? But for optional we might want to wrap?
    // For simplicity, if no grouping and no alternation, consider simple if no '(' and no '|'
    if !s.contains('|') && !s.contains('(') && !s.contains(')') {
        return true;
    }
    false
}

fn make_optional(s: &str) -> String {
    if s.is_empty() {
        return "".to_string();
    }
    if is_simple_regex(s) {
        format!("{}?", s)
    } else {
        format!("(?:{})?", s)
    }
}

fn gen_node(node: &Node) -> String {
    if node.children.is_empty() {
        return "".to_string();
    }
    // Group children by suffix regex
    let mut suffix_to_first: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (first, child) in &node.children {
        let suffix = gen_node(child);
        suffix_to_first.entry(suffix).or_default().push(first.clone());
    }

    let mut merged_branches: Vec<String> = Vec::new();

    for (suffix, first_chars) in suffix_to_first.iter() {
        if first_chars.len() > 1 {
            let (cc_opt, multi) = build_char_class(first_chars);
            if let Some(cc) = cc_opt {
                merged_branches.push(format!("{}{}", cc, suffix));
                for m in multi {
                    let esc = escape_literal(&m);
                    merged_branches.push(format!("{}{}", esc, suffix));
                }
            } else {
                for fc in first_chars {
                    let esc = escape_literal(fc);
                    merged_branches.push(format!("{}{}", esc, suffix));
                }
            }
        } else {
            let fc = &first_chars[0];
            let esc = escape_literal(fc);
            merged_branches.push(format!("{}{}", esc, suffix));
        }
    }

    // Handle is_end (empty alternative)
    if node.is_end {
        if merged_branches.is_empty() {
            return "".to_string();
        }
        if merged_branches.len() == 1 {
            let br = &merged_branches[0];
            return make_optional(br);
        } else {
            // Multiple branches + empty
            // Try to absorb empty into a single-char branch
            // Find if any branch is single char or char class
            // For simplicity, we'll check if any branch is simple and can be made optional to absorb empty
            // We'll convert first simple branch to optional and keep others

            // Check if any branch is simple
            let mut has_simple = false;
            for b in &merged_branches {
                if is_simple_regex(b) {
                    has_simple = true;
                    break;
                }
            }
            if has_simple {
                let mut new_merged: Vec<String> = Vec::new();
                let mut used = false;
                for b in merged_branches {
                    if !used && is_simple_regex(&b) {
                        new_merged.push(format!("{}?", b));
                        used = true;
                    } else {
                        new_merged.push(b);
                    }
                }
                // sort descending length then alphabetical
                new_merged.sort_by(|a, b| {
                    let ord_len = b.len().cmp(&a.len());
                    if ord_len != std::cmp::Ordering::Equal {
                        ord_len
                    } else {
                        a.cmp(b)
                    }
                });
                let inner = new_merged.join("|");
                return format!("(?:{})", inner);
            } else {
                // No simple branch, make whole optional
                let mut sorted = merged_branches.clone();
                sorted.sort_by(|a, b| {
                    let ord_len = b.len().cmp(&a.len());
                    if ord_len != std::cmp::Ordering::Equal {
                        ord_len
                    } else {
                        a.cmp(b)
                    }
                });
                let inner = sorted.join("|");
                return format!("(?:{})?", inner);
            }
        }
    } else {
        if merged_branches.len() == 1 {
            return merged_branches[0].clone();
        } else {
            // sort descending length then alphabetical for alternation
            let mut sorted = merged_branches.clone();
            sorted.sort_by(|a, b| {
                let ord_len = b.len().cmp(&a.len());
                if ord_len != std::cmp::Ordering::Equal {
                    ord_len
                } else {
                    a.cmp(b)
                }
            });
            let inner = sorted.join("|");
            return format!("(?:{})", inner);
        }
    }
}

// For char conversions
fn convert_graphemes(s: &str, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> String {
    // For each codepoint in s, convert based on precedence
    // But note: s may be multi-codepoint grapheme that we treat as separate codepoints for conversion as observed for y̆
    // So we will work per char (Unicode scalar), not per grapheme, for conversion.

    let mut result = String::new();
    for c in s.chars() {
        let converted = convert_char(c, digits, non_digits, spaces, non_spaces, words, non_words);
        result.push_str(&converted);
    }
    result
}

fn convert_char(c: char, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> String {
    // Precedence: s > d > w > D > W > S
    // Determine properties
    let is_d = is_digit_char(c);
    let is_w = is_word_char(c);
    let is_s = is_space_char(c);
    // is_D = !is_d, is_W = !is_w, is_S = !is_s

    if spaces && is_s {
        return "\\s".to_string();
    }
    if digits && is_d {
        return "\\d".to_string();
    }
    if words && is_w {
        // But need to check if digit takes precedence already handled
        return "\\w".to_string();
    }
    if non_digits && !is_d {
        return "\\D".to_string();
    }
    if non_words && !is_w {
        return "\\W".to_string();
    }
    if non_spaces && !is_s {
        return "\\S".to_string();
    }
    // No conversion, escape if needed
    if ".^$*+?()[]{}|\\".contains(c) {
        format!("\\{}", c)
    } else {
        c.to_string()
    }
}

// Repetition handling for single string
fn find_repetition(s: &str, min_sub_len: u32, min_rep: u32) -> Option<(usize, usize, usize)> {
    // Find first repetition starting at any position? For simplicity, left-to-right scan for any substring that repeats
    // Returns (start, sub_len, count) where count >= min_rep+1 total occurrences
    // For simplicity, we scan for smallest start where repetition found? We'll try to mimic observed behavior which prefers later start that covers to end.

    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    if n == 0 {
        return None;
    }
    // Prefer later start? We'll scan from end backwards maybe?
    // For "abcabcab", we want start=2, len=3, count=2
    // For "aaaa", we want start=0, len=1, count=4

    // Let's attempt to find all possible repetitions and pick one with best criteria:
    // Criteria we guess: prefer repetition that covers suffix to end (i.e., start + len*count == n)
    // Among those, prefer smallest len? Or something

    let mut candidates = Vec::new();

    for start in 0..n {
        for l in (min_sub_len as usize)..=n {
            if start + l > n {
                break;
            }
            if start + l * 2 > n && min_rep == 1 {
                // Need at least 2 occurrences, so start + 2*l <= n OR partial? For "abcabcab", l=3, start=2, need 2 occurrences: 2+3*2=8 which equals n=8, so ok. For start=0,l=3, need 2*3=6 <=8, ok.
            }
            if l < min_sub_len as usize {
                continue;
            }
            // Count how many consecutive repeats
            let mut count = 1;
            let mut pos = start + l;
            while pos + l <= n {
                // check if substring chars[start..start+l] == chars[pos..pos+l]
                if chars[start..start+l] == chars[pos..pos+l] {
                    count += 1;
                    pos += l;
                } else {
                    break;
                }
            }
            if count >= (min_rep as usize + 1) {
                candidates.push((start, l, count));
            }
        }
    }

    if candidates.is_empty() {
        return None;
    }

    // Now choose best candidate
    // Heuristic: prefer candidate that ends at n (covers to end), then smallest start? Actually for "abcabcab", candidates include (0,3,2) ends at 6 not n, and (2,3,2) ends at 8 = n. So prefer ends at n.
    // Among those ending at n, pick smallest start? For "abcabcab", only (2,3,2) ends at n, so pick it.

    // For "aaaa": candidates (0,1,4) ends at 4=n, (0,2,2) ends at 4=n, (1,1,3) ends at 4=n, etc. Many end at n. Which to pick? Observed picks (0,1,4) len1. So among those ending at n, pick smallest len? That would be len1.

    // For "ababa": candidates: (0,2,2) "ab" at 0 repeats 2 leaving "a" -> start0 len2 count2 ends at 4 not n=5, so ends at 4. (1,2,2) "ba" at1 repeats 2 ending at 5=n. So (1,2,2) ends at n, (0,2,2) ends not at n. Prefer ends at n, so pick (1,2,2). That matches observed a(ba){2}.

    // For "abcabca": candidates (0,3,2) ends at 6 leaving "a", (1,3,2) ends at 7=n. So pick (1,3,2) => a(bca){2} matches.

    // So heuristic: prefer candidates ending at n.

    let mut ending_at_n: Vec<_> = candidates.iter().filter(|(st,l,c)| st + l*c == n).cloned().collect();
    if !ending_at_n.is_empty() {
        // Among those, pick smallest start? Or smallest len? For "aaaa", starts 0,1,2,3 all end at n? Let's see: start0 len1 count4 ends at4, start1 len1 count3 ends at4, start2 len1 count2 ends at4, start3 len1 count1? Need count>=2, so start3 len1 count1 not enough. So candidates ending at n include (0,1,4),(1,1,3),(2,1,2). Also (0,2,2) ends at4, (1,2,1?) no. So many. Which to pick? Pick smallest len first? Among len1 candidates, smallest start is 0. So pick (0,1,4). That matches.

        // For "abcabcab", only (2,3,2) ends at n, so pick it.

        // For "ababa", ending at n candidates: (1,2,2) ends at5=n, (0,2,2) ends at4 not n, (0,1,1?) not enough, (2,2,1?)... Actually (0,2,2) ends at4, not n, so only (1,2,2) ends at n? Let's check (0,1,2?) "a" at0 repeats? No. So (1,2,2) is the only ending at n with len>=1. So pick it.

        // So among ending_at_n, pick smallest start? Or smallest len? For "aaaa", among ending_at_n, we have (0,1,4) start0 len1, (0,2,2) start0 len2, (1,1,3) start1 len1, (2,1,2) start2 len1. Smallest start is 0, among start0, smallest len is 1 => (0,1,4). So pick (0,1,4).

        // Let's implement: sort by start ascending, then len ascending
        ending_at_n.sort_by(|a,b| {
            let ord_start = a.0.cmp(&b.0);
            if ord_start != std::cmp::Ordering::Equal {
                return ord_start;
            }
            a.1.cmp(&b.1)
        });
        return Some(ending_at_n[0]);
    }

    // If no candidate ends at n, pick smallest start then smallest len? For "abcabcab", if we didn't have ending_at_n, we would pick start0 len3.

    // But for general, we might want to pick candidate that leaves minimal remainder? For "abcabcab", (0,3,2) leaves "ab" remainder length2, (2,3,2) leaves "ab" prefix length2. Both leave 2 chars uncovered. So tie.

    candidates.sort_by(|a,b| {
        let ord_start = a.0.cmp(&b.0);
        if ord_start != std::cmp::Ordering::Equal {
            return ord_start;
        }
        a.1.cmp(&b.1)
    });
    Some(candidates[0])
}

fn convert_repetition_single(s: &str, min_sub_len: u32, min_rep: u32) -> String {
    // Greedy left-to-right using find_repetition for whole remaining?
    // We'll attempt iterative: result parts, i=0
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i = 0;
    while i < n {
        let remaining: String = chars[i..].iter().collect();
        if let Some((start, l, count)) = find_repetition(&remaining, min_sub_len, min_rep) {
            // start is relative to remaining
            if start > 0 {
                // emit literal prefix of length start
                let prefix: String = chars[i..i+start].iter().collect();
                // Escape prefix literal
                result.push_str(&escape_literal(&prefix));
                i += start;
                continue;
            } else {
