            res.push_str("\x1b[1;32m)\x1b[0m");
            i+=1;
            continue;
        }
        if bytes[i] == b'|' {
            res.push_str("\x1b[1;31m|\x1b[0m");
            i+=1;
            continue;
        }
        if bytes[i] == b'?' {
            // Check if it's part of quantifier after group or char class or literal
            // Color as 1;35
            res.push_str("\x1b[1;35m?\x1b[0m");
            i+=1;
            continue;
        }
        if bytes[i] == b'^' || bytes[i] == b'$' {
            res.push_str("\x1b[1;33m");
            res.push(bytes[i] as char);
            res.push_str("\x1b[0m");
            i+=1;
            continue;
        }
        if bytes[i] == b'[' {
            res.push_str("\x1b[1;36m[\x1b[0m");
            i+=1;
            continue;
        }
        if bytes[i] == b']' {
            res.push_str("\x1b[1;36m]\x1b[0m");
            i+=1;
            continue;
        }
        if bytes[i] == b'-' {
            // Inside char class, '-' colored as 1;36, outside? In "[a-c]" the '-' between a and c is colored? Observed "[a\1;36m-\0mc" yes inside class '-' colored as 1;36
            // Outside char class, '-' is literal? In "a-b" outside class, it's escaped as "\-" . So "-" alone not inside class would be escaped? Actually "a-b" alone gave "a\-b" where "\-" includes "-" escaped. The "-" after "\" should be? The escape "\-" - the "\" is not colored? In observed for "a-b" without color, it's "a\-b". With color, we need to see color for "\-"? We didn't test color for "a-b". Let's test later.

            // For now, if we are inside char class context, color '-', else treat as literal.

            // We need to track in_class state. Let's add simple tracking.

            res.push_str("\x1b[1;36m-\x1b[0m");
            i+=1;
            continue;
        }
        if s[i..].starts_with("\\d") || s[i..].starts_with("\\w") || s[i..].starts_with("\\s") || s[i..].starts_with("\\D") || s[i..].starts_with("\\W") || s[i..].starts_with("\\S") {
            res.push_str("\x1b[103;30m");
            res.push_str(&s[i..i+2]);
            res.push_str("\x1b[0m");
            i+=2;
            continue;
        }
        if bytes[i] == b'{' {
            // Find closing '}'
            if let Some(close) = s[i..].find('}') {
                let token = &s[i..i+close+1];
                res.push_str("\x1b[104;37m");
                res.push_str(token);
                res.push_str("\x1b[0m");
                i += token.len();
                continue;
            }
        }
        // Default: copy char
        res.push(bytes[i] as char);
        i+=1;
    }

    res
}

fn colorize_verbose(_s: &str) -> String {
    // For verbose, similar but with newlines and indentation
    // We'll reuse same logic but preserve newlines and indentation

    // For verbose, colors should still be applied to tokens even with indentation

    // Observed verbose colorized:
    // (?x) colored 40;93
    // ^ and $ colored 1;33 even on their own lines
    // [ ] - colored 1;36
    // (?: ) colored 1;32
    // | colored 1;31
