#[derive(Debug, Clone)]
struct Node {
    children: BTreeMap<String, Node>,
    is_end: bool,
}

impl Node {
    fn new() -> Self {
        Node {
            children: BTreeMap::new(),
            is_end: false,
        }
    }

    fn insert(&mut self, graphemes: &[String]) {
        if graphemes.is_empty() {
            self.is_end = true;
            return;
        }
        let first = graphemes[0].clone();
        let child = self.children.entry(first).or_insert_with(Node::new);
        child.insert(&graphemes[1..]);
    }
}

fn is_digit_char(c: char) -> bool {
    c.is_digit(10)
}

fn is_space_char(c: char) -> bool {
    c.is_whitespace()
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn escape_literal_str(s: &str) -> String {
    let mut res = String::new();
    for g in s.graphemes(true) {
        if g.chars().count() == 1 {
            let c = g.chars().next().unwrap();
            if ".^$*+?()[]{}|\\".contains(c) {
                res.push('\\');
                res.push(c);
            } else {
                res.push_str(g);
            }
        } else {
            res.push_str(g);
        }
    }
    res
}

fn escape_inside_class(c: char) -> String {
    match c {
        '\\' | ']' | '[' | '^' | '-' => format!("\\{}", c),
        _ => c.to_string(),
    }
}

fn build_char_class(chars: &[String]) -> (Option<String>, Vec<String>) {
    let mut single: Vec<char> = Vec::new();
    let mut multi: Vec<String> = Vec::new();
    for ch in chars {
        if ch.graphemes(true).count() == 1 && ch.chars().count() == 1 {
            single.push(ch.chars().next().unwrap());
        } else {
            // Check if it's single codepoint but multi grapheme? Actually grapheme count 1 but char count may be >1 (combining)
            // For combining, we treat as multi (not char class)
            if ch.chars().count() == 1 {
                single.push(ch.chars().next().unwrap());
            } else {
                multi.push(ch.clone());
            }
        }
    }
    if single.is_empty() {
        return (None, multi);
    }
    let mut set: BTreeSet<char> = BTreeSet::new();
    for c in single {
        set.insert(c);
    }
    let sorted: Vec<char> = set.into_iter().collect();
    let mut runs: Vec<Vec<char>> = Vec::new();
    let mut cur: Vec<char> = Vec::new();
    for &c in &sorted {
        if cur.is_empty() {
            cur.push(c);
        } else {
            if c as u32 == cur.last().unwrap().clone() as u32 + 1 {
                cur.push(c);
            } else {
                runs.push(cur);
                cur = vec![c];
            }
        }
    }
    if !cur.is_empty() {
        runs.push(cur);
    }
    let mut content = String::new();
    for run in runs {
        if run.len() >= 3 {
            content.push_str(&escape_inside_class(run[0]));
            content.push('-');
            content.push_str(&escape_inside_class(run[run.len() - 1]));
        } else {
            for c in run {
                content.push_str(&escape_inside_class(c));
            }
        }
    }
    (Some(format!("[{}]", content)), multi)
}

fn is_simple(s: &str) -> bool {
    if s.is_empty() {
        return true;
    }
    // Simple if no '|' and not starting with "(?:"
    // Also check if it's [..] or \d etc
    // For our purposes: simple if it contains no '|' and no '('.
    // Also \d,\w etc are simple (contain '\' but no '|')
    // This is heuristic for optional handling
    if s.contains('|') {
        return false;
    }
    if s.starts_with('(') {
        // Check if it's (?:...) or (...)
        // For simplicity, if it starts with "(?:" and ends with ")" and contains no '|' inside? Actually (?:ab) still contains no '|', but it's grouping
        // For optional, we want to avoid double wrapping? 
        // We'll consider "(?:...)" as not simple if it contains '?' inside?
        // For our make_optional, we will wrap if not simple
        // So if s starts with '(' it's not simple (needs wrapping)
        return false;
    }
    // Also if s contains '{' or '}' maybe not simple? Actually a{3} is simple? For optional, a{3}? would be a{3}? which is okay? But original makes (?:ab){3}? etc.
    // For repetition case, "(?:ab){3}" is not simple, but making it optional would be "(?:ab){3}?"? Actually need "(?:(?:ab){3})?" ?

    true
}

fn make_optional(s: &str) -> String {
    if s.is_empty() {
        return "".to_string();
    }
    if is_simple(s) {
        format!("{}?", s)
    } else {
        format!("(?:{})?", s)
    }
}

fn gen_node(node: &Node) -> String {
    if node.children.is_empty() {
        return "".to_string();
    }
    // Group by suffix
    let mut suffix_to_first: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (first, child) in &node.children {
        let suffix = gen_node(child);
        suffix_to_first.entry(suffix).or_default().push(first.clone());
    }

    let mut merged: Vec<String> = Vec::new();
    for (suffix, first_chars) in suffix_to_first.iter() {
        if first_chars.len() > 1 {
            let (cc_opt, multi) = build_char_class(first_chars);
            if let Some(cc) = cc_opt {
                merged.push(format!("{}{}", cc, suffix));
                for m in multi {
                    merged.push(format!("{}{}", escape_literal_str(m), suffix));
                }
            } else {
                for fc in first_chars {
                    merged.push(format!("{}{}", escape_literal_str(fc), suffix));
                }
            }
        } else {
            let fc = &first_chars[0];
            merged.push(format!("{}{}", escape_literal_str(fc), suffix));
        }
    }

    if node.is_end {
        if merged.is_empty() {
            return "".to_string();
        }
        if merged.len() == 1 {
            let br = &merged[0];
            return make_optional(br);
        } else {
            // Check if we can absorb empty into a single-char branch
            // Find simple branches
            let mut has_simple = false;
            for b in &merged {
                if is_simple(b) {
                    has_simple = true;
                    break;
                }
            }
            if has_simple {
                let mut new_merged: Vec<String> = Vec::new();
                let mut used = false;
                for b in merged {
                    if !used && is_simple(&b) {
                        new_merged.push(format!("{}?", b));
                        used = true;
                    } else {
                        new_merged.push(b);
                    }
                }
                // sort descending length then alphabetical
                new_merged.sort_by(|a, b| {
                    let ord = b.len().cmp(&a.len());
                    if ord != std::cmp::Ordering::Equal {
                        ord
                    } else {
                        a.cmp(b)
                    }
                });
                let inner = new_merged.join("|");
                return format!("(?:{})", inner);
            } else {
                let mut sorted = merged.clone();
                sorted.sort_by(|a, b| {
                    let ord = b.len().cmp(&a.len());
                    if ord != std::cmp::Ordering::Equal {
                        ord
                    } else {
                        a.cmp(b)
                    }
                });
                let inner = sorted.join("|");
                return format!("(?:{})?", inner);
            }
        }
    } else {
        if merged.len() == 1 {
            return merged[0].clone();
        } else {
            let mut sorted = merged.clone();
            sorted.sort_by(|a, b| {
                let ord = b.len().cmp(&a.len());
                if ord != std::cmp::Ordering::Equal {
                    ord
                } else {
                    a.cmp(b)
                }
            });
            let inner = sorted.join("|");
            return format!("(?:{})", inner);
        }
    }
}

// For char conversions
fn convert_char(c: char, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> String {
    let is_d = is_digit_char(c);
    let is_w = is_word_char(c);
    let is_s = is_space_char(c);
    if spaces && is_s {
        return "\\s".to_string();
    }
    if digits && is_d {
        return "\\d".to_string();
    }
    if words && is_w {
        return "\\w".to_string();
    }
    if non_digits && !is_d {
        return "\\D".to_string();
    }
    if non_words && !is_w {
        return "\\W".to_string();
    }
    if non_spaces && !is_s {
        return "\\S".to_string();
    }
    if ".^$*+?()[]{}|\\".contains(c) {
        format!("\\{}", c)
    } else {
        c.to_string()
    }
}

fn convert_string(s: &str, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool, escape: bool, with_surrogates: bool) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if escape && !c.is_ascii() {
            let cp = c as u32;
            if with_surrogates && cp >= 0x10000 {
                // Convert to surrogate pair
                let cp_prime = cp - 0x10000;
                let high = 0xD800 + ((cp_prime >> 10) & 0x3FF);
                let low = 0xDC00 + (cp_prime & 0x3FF);
                out.push_str(&format!("\\u{{{:x}}}\\u{{{:x}}}", high, low));
            } else {
                out.push_str(&format!("\\u{{{:x}}}", cp));
            }
        } else {
            out.push_str(&convert_char(c, digits, non_digits, spaces, non_spaces, words, non_words));
        }
    }
    out
}

// Repetition for single string (simple)
fn find_rep(s: &str, min_sub_len: usize, min_rep: usize) -> Option<(usize, usize, usize)> {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    if n == 0 {
        return None;
    }
    let mut cands = Vec::new();
    for start in 0..n {
        for l in min_sub_len..=n {
            if start + l > n {
                break;
            }
            // need at least min_rep+1 total
            if start + l * (min_rep + 1) > n {
                // For cases where repetition doesn't need to fill all, we allow partial? For "abcabcab", start 2 l 3 count2 needs start+ l*2 =8 ==n, ok. For start0 l3 count2 needs 0+6=6 <=8, ok.
                // So we need start + l*(min_rep+1) <= n
                if start + l * (min_rep + 1) > n {
                    continue;
                }
            }
            let mut cnt = 1;
            let mut pos = start + l;
            while pos + l <= n {
                if chars[start..start+l] == chars[pos..pos+l] {
                    cnt += 1;
                    pos += l;
                } else {
                    break;
                }
            }
            if cnt >= min_rep + 1 {
                cands.push((start, l, cnt));
            }
        }
    }
    if cands.is_empty() {
        return None;
    }
    // Prefer ending at n
    let mut ending: Vec<_> = cands.iter().filter(|(st,l,c)| st + l*c == n).cloned().collect();
    if !ending.is_empty() {
        ending.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
        return Some(ending[0]);
    }
    cands.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    Some(cands[0])
}

fn convert_rep_single(s: &str, min_sub_len: u32, min_rep: u32) -> String {
    let mut res = String::new();
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i = 0;
    while i < n {
        let remaining: String = chars[i..].iter().collect();
        if let Some((start, l, cnt)) = find_rep(&remaining, min_sub_len as usize, min_rep as usize) {
            if start > 0 {
                let prefix: String = chars[i..i+start].iter().collect();
                res.push_str(&escape_literal_str(&prefix));
                i += start;
                continue;
            } else {
                let sub: String = chars[i..i+l].iter().collect();
                let esc = escape_literal_str(&sub);
                if l == 1 {
                    res.push_str(&format!("{}{{{}}}", esc, cnt));
                } else {
                    res.push_str(&format!("(?:{}){{{}}}", esc, cnt));
                }
                i += l * cnt;
                continue;
            }
        } else {
            let c = chars[i];
            if ".^$*+?()[]{}|\\".contains(c) {
                res.push('\\');
                res.push(c);
            } else {
                res.push(c);
            }
            i += 1;
        }
    }
    res
}

// For formatting

fn format_verbose(regex: &str, no_start: bool, no_end: bool, ignore_case: bool, capture_groups: bool) -> String {
    // We need to parse regex and pretty print with indentation
    // Simplistic: We have base regex like ^a(?:bc?)?$
    // For verbose, we need to output:
    // (?x)
    // ^
    //   a
    //   (?:
    //     bc?
    //   )?
    // $
    // etc.

    // We'll implement a custom formatter that traverses regex string and formats.

