    let n = tokens.len();
    let mut i = 0;
    while i < n {
        // Try to find rep starting at i
        let mut found = None;
        // Try lengths from min_sub_len to (n - i) / (min_rep+1)
        for l in min_sub_len..=n {
            if i + l * (min_rep + 1) > n {
                break;
            }
            // Count consecutive repeats of tokens[i..i+l]
            let mut cnt = 1;
            let mut pos = i + l;
            while pos + l <= n {
                if tokens[i..i+l] == tokens[pos..pos+l] {
                    cnt += 1;
                    pos += l;
                } else {
                    break;
                }
            }
            if cnt >= min_rep + 1 {
                found = Some((l,cnt));
                break; // pick smallest l that repeats
            }
        }
        if let Some((l,cnt)) = found {
            // Build token for repeated substring
            let sub_tokens = &tokens[i..i+l];
            let sub_str = sub_tokens.join("");
            let esc = sub_str; // already escaped
            let rep_token = if l == 1 {
                format!("{}{{{}}}", esc, cnt)
            } else {
                format!("(?:{}){{{}}}", esc, cnt)
            };
            result.push(rep_token);
            i += l * cnt;
