          Reads test cases on separate lines from a file.

          Lines may be ended with either a newline `\n` or a carriage return with a line feed
          `\r\n`. The final line ending is optional.

          Use a hyphen `-` to read the filename from standard input.

          Conflicts with INPUT...

Digit Options:
  -d, --digits
          Converts any Unicode decimal digit to \d.

          Takes precedence over --words if both are set. Decimal digits are converted to \d,
          remaining word characters to \w.

          Takes precedence over --non-spaces if both are set. Decimal digits are converted to \d,
          remaining non-space characters to \S.

  -D, --non-digits
          Converts any character which is not a Unicode decimal digit to \D.

          Takes precedence over --non-words if both are set. Non-digits which are also non-word
          characters are converted to \D.

          Takes precedence over --non-spaces if both are set. Non-digits which are also non-space
          characters are converted to \D.

Whitespace Options:
  -s, --spaces
          Converts any Unicode whitespace character to \s.

          Takes precedence over --non-digits if both are set. Whitespace is converted to \s,
          remaining non-digits to \D.

          Takes precedence over --non-words if both are set. Whitespace is converted to \s,
          remaining non-word characters to \W.

  -S, --non-spaces
          Converts any character which is not a Unicode whitespace character to \S

Word Options:
  -w, --words
          Converts any Unicode word character to \w.

          Takes precedence over --non-digits if both are set. Word characters are converted to \w,
          remaining non-digits to \D.

          Takes precedence over --non-spaces if both are set. Word characters are converted to \w,
          remaining non-whitespace to \S.

  -W, --non-words
          Converts any character which is not a Unicode word character to \W.

          Takes precedence over --non-spaces if both are set. Non-word characters which are also
          non-whitespace are converted to \W.

Escaping Options:
  -e, --escape
          Replaces all non-ASCII characters with unicode escape sequences

      --with-surrogates
          Converts astral code points to surrogate pairs if --escape is set

Repetition Options:
  -r, --repetitions
          Detects repeated non-overlapping substrings and converts them to {{min,max}} quantifier
          notation

      --min-repetitions <QUANTITY>
          Specifies the minimum quantity of substring repetitions to be converted if --repetitions
          is set

          [default: 1]

      --min-substring-length <LENGTH>
          Specifies the minimum length a repeated substring must have in order to be converted if
          --repetitions is set

          [default: 1]

Anchor Options:
      --no-start-anchor
          Removes the caret anchor `^` from the resulting regular expression.

          By default, the caret anchor is added to every generated regular expression which
          guarantees that the expression matches the test cases given as input only at the start of
          a string.

          This flag removes the anchor, thereby allowing to match the test cases also when they do
          not occur at the start of a string.

      --no-end-anchor
          Removes the dollar sign anchor `$` from the resulting regular expression.

          By default, the dollar sign anchor is added to every generated regular expression which
          guarantees that the expression matches the test cases given as input only at the end of a
          string.

          This flag removes the anchor, thereby allowing to match the test cases also when they do
          not occur at the end of a string.

      --no-anchors
          Removes the caret and dollar sign anchors from the resulting regular expression.

          By default, anchors are added to every generated regular expression which guarantees that
          the expression exactly matches only the test cases given as input and nothing else.

          This flag removes the anchors, thereby allowing to match the test cases also when they
          occur within a larger string that contains other content as well.

Display Options:
  -x, --verbose
          Produces a nicer-looking regular expression in verbose mode

  -c, --colorize
          Provides syntax highlighting for the resulting regular expression

Miscellaneous Options:
  -i, --ignore-case
          Performs case-insensitive matching, letters match both upper and lower case

  -g, --capture-groups
          Replaces non-capturing groups with capturing ones

  -h, --help
          Prints help information

  -v, --version
          Prints version information
"#);
}

#[derive(Debug, Clone)]
struct Node {
    children: BTreeMap<String, Node>,
    is_end: bool,
}

impl Node {
    fn new() -> Self {
        Node { children: BTreeMap::new(), is_end: false }
    }
    fn insert(&mut self, tokens: &[String]) {
        if tokens.is_empty() {
            self.is_end = true;
            return;
        }
        let first = tokens[0].clone();
        let child = self.children.entry(first).or_insert_with(Node::new);
        child.insert(&tokens[1..]);
    }
}

fn is_digit_char(c: char) -> bool { c.is_digit(10) }
fn is_space_char(c: char) -> bool { c.is_whitespace() }
fn is_word_char(c: char) -> bool { c.is_alphanumeric() || c == '_' }

fn escape_literal_str(s: &str) -> String {
    let mut res = String::new();
    for g in s.graphemes(true) {
        if g.chars().count()==1 {
            let c = g.chars().next().unwrap();
            if ".^$*+?()[]{}|\\".contains(c) {
                res.push('\\'); res.push(c);
            } else { res.push_str(g); }
        } else { res.push_str(g); }
    }
    res
}

fn escape_inside_class(c: char) -> String {
    match c {
        '\\' | ']' | '[' | '^' | '-' => format!("\\{}", c),
        _ => c.to_string(),
    }
}

fn build_char_class(chars: &[String]) -> (Option<String>, Vec<String>) {
    let mut single: Vec<char> = Vec::new();
    let mut multi: Vec<String> = Vec::new();
    for ch in chars {
        if ch.graphemes(true).count()==1 && ch.chars().count()==1 {
            single.push(ch.chars().next().unwrap());
        } else {
            if ch.chars().count()==1 {
                single.push(ch.chars().next().unwrap());
            } else {
                multi.push(ch.clone());
            }
        }
    }
    if single.is_empty() { return (None, multi); }
    let mut set: BTreeSet<char> = BTreeSet::new();
    for c in single { set.insert(c); }
    let sorted: Vec<char> = set.into_iter().collect();
    let mut runs: Vec<Vec<char>> = Vec::new();
    let mut cur: Vec<char> = Vec::new();
    for &c in &sorted {
        if cur.is_empty() { cur.push(c); }
        else {
            if c as u32 == cur.last().unwrap().clone() as u32 + 1 { cur.push(c); }
            else { runs.push(cur); cur = vec![c]; }
        }
    }
    if !cur.is_empty() { runs.push(cur); }
    let mut content = String::new();
    for run in runs {
        if run.len()>=3 {
            content.push_str(&escape_inside_class(run[0]));
            content.push('-');
            content.push_str(&escape_inside_class(run[run.len()-1]));
        } else {
            for c in run { content.push_str(&escape_inside_class(c)); }
        }
    }
    (Some(format!("[{}]", content)), multi)
}

fn is_simple(s: &str) -> bool {
    if s.is_empty() { return true; }
    if s.contains('|') { return false; }
    if s.starts_with('(') { return false; }
    if s.contains('?') || s.contains('{') || s.contains('}') { return false; }
    true
}

fn make_optional(s: &str) -> String {
    if s.is_empty() { return "".to_string(); }
    if is_simple(s) { format!("{}?", s) } else { format!("(?:{})?", s) }
}

fn gen_node(node: &Node) -> String {
    if node.children.is_empty() { return "".to_string(); }
    let mut suffix_to_first: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (first, child) in &node.children {
        let suffix = gen_node(child);
        suffix_to_first.entry(suffix).or_default().push(first.clone());
    }
    let mut merged: Vec<String> = Vec::new();
    for (suffix, first_chars) in suffix_to_first.iter() {
        if first_chars.len()>1 {
            let (cc_opt, multi) = build_char_class(first_chars);
            if let Some(cc) = cc_opt {
                merged.push(format!("{}{}", cc, suffix));
                for m in multi { merged.push(format!("{}{}", escape_literal_str(m), suffix)); }
            } else {
                for fc in first_chars { merged.push(format!("{}{}", escape_literal_str(fc), suffix)); }
            }
        } else {
            let fc = &first_chars[0];
            merged.push(format!("{}{}", escape_literal_str(fc), suffix));
        }
    }

    if node.is_end {
        if merged.is_empty() { return "".to_string(); }
        if merged.len()==1 {
            return make_optional(&merged[0]);
        } else {
            // Try absorb empty into simple branch
            let has_simple = merged.iter().any(|b| is_simple(b));
            if has_simple {
                let mut new_merged: Vec<String> = Vec::new();
                let mut used = false;
                for b in merged {
                    if !used && is_simple(&b) {
                        new_merged.push(format!("{}?", b));
                        used = true;
                    } else { new_merged.push(b); }
                }
                let mut sorted = new_merged.clone();
                sorted.sort_by(|a,b| { let o = b.len().cmp(&a.len()); if o!=std::cmp::Ordering::Equal { o } else { a.cmp(b) } });
                let inner = sorted.join("|");
                return format!("(?:{})", inner);
            } else {
                let mut sorted = merged.clone();
                sorted.sort_by(|a,b| { let o = b.len().cmp(&a.len()); if o!=std::cmp::Ordering::Equal { o } else { a.cmp(b) } });
                let inner = sorted.join("|");
                return format!("(?:{})?", inner);
            }
        }
    } else {
        if merged.len()==1 { return merged[0].clone(); }
        let mut sorted = merged.clone();
        sorted.sort_by(|a,b| { let o = b.len().cmp(&a.len()); if o!=std::cmp::Ordering::Equal { o } else { a.cmp(b) } });
        let inner = sorted.join("|");
        return format!("(?:{})", inner);
    }
}

fn convert_char(c: char, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> String {
    let is_d = is_digit_char(c);
    let is_w = is_word_char(c);
    let is_s = is_space_char(c);
    if spaces && is_s { return "\\s".to_string(); }
    if digits && is_d { return "\\d".to_string(); }
    if words && is_w { return "\\w".to_string(); }
    if non_digits && !is_d { return "\\D".to_string(); }
    if non_words && !is_w { return "\\W".to_string(); }
    if non_spaces && !is_s { return "\\S".to_string(); }
    if ".^$*+?()[]{}|\\".contains(c) { format!("\\{}", c) } else { c.to_string() }
}

fn convert_string(s: &str, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool, escape: bool, with_surrogates: bool) -> Vec<String> {
    let mut tokens: Vec<String> = Vec::new();
    for c in s.chars() {
        if escape && !c.is_ascii() {
            let cp = c as u32;
            if with_surrogates && cp>=0x10000 {
                let cp_prime = cp-0x10000;
                let high = 0xD800 + ((cp_prime>>10)&0x3FF);
                let low = 0xDC00 + (cp_prime & 0x3FF);
                tokens.push(format!("\\u{{{:x}}}", high));
                tokens.push(format!("\\u{{{:x}}}", low));
            } else {
                tokens.push(format!("\\u{{{:x}}}", cp));
            }
        } else {
            tokens.push(convert_char(c, digits, non_digits, spaces, non_spaces, words, non_words));
        }
    }
    tokens
}

fn find_rep_tokens(tokens: &[String], min_sub_len: usize, min_rep: usize) -> Option<(usize, usize, usize)> {
    let n = tokens.len();
    if n==0 { return None; }
    let mut cands: Vec<(usize,usize,usize)> = Vec::new();
    for start in 0..n {
        for l in min_sub_len..=n {
            if start + l > n { break; }
            if start + l * (min_rep+1) > n { continue; }
            let mut cnt=1;
            let mut pos=start+l;
            while pos + l <= n {
                if tokens[start..start+l]==tokens[pos..pos+l] { cnt+=1; pos+=l; } else { break; }
            }
            if cnt >= min_rep+1 { cands.push((start,l,cnt)); }
        }
    }
    if cands.is_empty() { return None; }
    let mut ending: Vec<_> = cands.iter().filter(|(st,l,c)| st + l*c == n).cloned().collect();
    if !ending.is_empty() {
        ending.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
        return Some(ending[0]);
    }
    cands.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    Some(cands[0])
}

fn convert_rep_tokens(mut tokens: Vec<String>, min_sub_len: usize, min_rep: usize) -> Vec<String> {
    let mut result: Vec<String> = Vec::new();
    let mut i=0;
    while i<tokens.len() {
        let remaining = &tokens[i..];
        if let Some((start,l,cnt)) = find_rep_tokens(remaining, min_sub_len, min_rep) {
            if start>0 {
                result.extend_from_slice(&tokens[i..i+start]);
                i+=start;
                continue;
            } else {
                let sub = tokens[i..i+l].join("");
                let rep = if l==1 { format!("{}{{{}}}", sub, cnt) } else { format!("(?:{}){{{}}}", sub, cnt) };
                result.push(rep);
                i+= l*cnt;
                continue;
            }
        } else {
            result.push(tokens[i].clone());
            i+=1;
        }
    }
    result
}

// Verbose formatting - simplified
fn split_top_level(s: &str) -> Vec<String> {
    let mut res: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut depth=0;
    let mut in_class=false;
    let mut esc=false;
    for c in s.chars() {
        if esc { cur.push(c); esc=false; continue; }
        if c=='\\' { cur.push(c); esc=true; continue; }
        if c=='[' && !in_class { in_class=true; cur.push(c); continue; }
        if c==']' && in_class { in_class=false; cur.push(c); continue; }
        if in_class { cur.push(c); continue; }
        if c=='(' { depth+=1; cur.push(c); continue; }
        if c==')' { depth-=1; cur.push(c); continue; }
        if c=='|' && depth==0 { res.push(cur); cur=String::new(); continue; }
        cur.push(c);
    }
    res.push(cur);
    res
}

fn parse_group(s: &str) -> (String, String) {
    // s like "(?:ab|cd)?" or "(?:ab){3}"
    let mut inner=String::new();
    let mut quant=String::new();
    if s.ends_with('?') {
        quant="?".to_string();
        let without = &s[..s.len()-1];
        if without.ends_with(')') {
            if without.starts_with("(?:") { inner=without[3..without.len()-1].to_string(); }
            else if without.starts_with('(') { inner=without[1..without.len()-1].to_string(); }
        }
    } else if let Some(close) = s.rfind('}') {
        if let Some(open) = s[..close].rfind('{') {
            if let Some(paren) = s[..open].rfind(')') {
                quant=s[open..=close].to_string();
                let without = &s[..paren+1];
                if without.starts_with("(?:") { inner=without[3..without.len()-1].to_string(); }
                else if without.starts_with('(') { inner=without[1..without.len()-1].to_string(); }
            }
        }
    } else {
        if s.starts_with("(?:") && s.ends_with(')') { inner=s[3..s.len()-1].to_string(); }
        else if s.starts_with('(') && s.ends_with(')') { inner=s[1..s.len()-1].to_string(); }
    }
    (inner, quant)
}

fn format_sequence(s: &str, indent: usize) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i=0;
    let mut literal_buf = String::new();

    while i<n {
        if s[i..].starts_with("(?:") || (chars[i]=='(') {
            if !literal_buf.is_empty() {
                lines.push(format!("{}{}", " ".repeat(indent), literal_buf));
                literal_buf.clear();
            }
            // find group end
            let start=i;
            let mut depth=0;
            let mut in_class=false;
            let mut esc=false;
            let mut j=i;
            while j<n {
                let c=chars[j];
                if esc { esc=false; j+=1; continue; }
                if c=='\\' { esc=true; j+=1; continue; }
                if c=='[' && !in_class { in_class=true; j+=1; continue; }
                if c==']' && in_class { in_class=false; j+=1; continue; }
                if in_class { j+=1; continue; }
                if c=='(' { depth+=1; }
                else if c==')' {
                    depth-=1;
                    if depth==0 {
                        j+=1;
                        if j<n && chars[j]=='?' { j+=1; }
                        else if j<n && chars[j]=='{' {
                            while j<n && chars[j]!='}' { j+=1; }
                            if j<n { j+=1; }
                        }
                        break;
                    }
                }
                j+=1;
            }
            let group_str = s[start..j].to_string();
            let (inner, quant) = parse_group(&group_str);
            if inner.contains('|') {
                lines.push(format!("{}(?:", " ".repeat(indent)));
                let branches = split_top_level(&inner);
                for (idx, br) in branches.iter().enumerate() {
                    if idx>0 { lines.push(format!("{}|", " ".repeat(indent+2))); }
                    let sub_lines = format_sequence(br, indent+2);
                    lines.extend(sub_lines);
                }
                lines.push(format!("{}{}){}", " ".repeat(indent), "", quant));
            } else {
                lines.push(format!("{}(?:", " ".repeat(indent)));
                let sub = format_sequence(&inner, indent+2);
                lines.extend(sub);
                lines.push(format!("{}{}){}", " ".repeat(indent), "", quant));
            }
            i=j;
            continue;
        } else if chars[i]=='[' {
            let start=i;
            let mut j=i+1;
            let mut esc=false;
            while j<n {
                let c=chars[j];
                if esc { esc=false; j+=1; continue; }
                if c=='\\' { esc=true; j+=1; continue; }
                if c==']' { j+=1; break; }
                j+=1;
            }
            if j<n && chars[j]=='?' { j+=1; }
            else if j<n && chars[j]=='{' {
                while j<n && chars[j]!='}' { j+=1; }
                if j<n { j+=1; }
            }
            let token = s[start..j].to_string();
            literal_buf.push_str(&token);
            i=j;
            continue;
        } else if chars[i]=='\\' {
            let start=i;
            let mut j=i+1;
            if j<n && chars[j]=='u' {
                j+=1;
                if j<n && chars[j]=='{' {
                    j+=1;
                    while j<n && chars[j]!='}' { j+=1; }
                    if j<n { j+=1; }
                }
            } else { j+=1; }
            if j<n && chars[j]=='?' { j+=1; }
            else if j<n && chars[j]=='{' {
                while j<n && chars[j]!='}' { j+=1; }
                if j<n { j+=1; }
            }
            let token = s[start..j].to_string();
            literal_buf.push_str(&token);
            i=j;
            continue;
        } else {
            // literal char, accumulate until next special
            let start=i;
            let mut j=i;
            while j<n {
                let c=chars[j];
                if c=='(' || c=='[' || c=='\\' { break; }
                j+=1;
            }
            let token = s[start..j].to_string();
            literal_buf.push_str(&token);
            i=j;
            continue;
        }
    }
    if !literal_buf.is_empty() {
        lines.push(format!("{}{}", " ".repeat(indent), literal_buf));
    }
    lines
}

fn format_verbose_body(s: &str) -> String {
    if s.is_empty() { return "".to_string(); }
    if !s.contains('(') && !s.contains('|') {
        return format!("  {}\n", s);
    }
    let lines = format_sequence(s, 2);
    lines.join("\n") + "\n"
}

fn colorize_token(s: &str) -> String {
    // Apply colors for plain (non-verbose) regex
    // We'll implement simple state machine that colors tokens as observed

    let mut res = String::new();
    let mut i=0;
    let chars: Vec<char> = s.chars().collect();
    let n=chars.len();
    let mut in_class=false;
    let mut esc=false;

    while i<n {
        if esc {
            res.push(chars[i]);
            esc=false;
            i+=1;
            continue;
        }
        if chars[i]=='\\' {
            // Check for \d etc
            if i+1<n {
                let next = chars[i+1];
                if "dDwWsS".contains(next) {
                    res.push_str("\x1b[103;30m");
                    res.push('\\'); res.push(next);
                    res.push_str("\x1b[0m");
                    i+=2;
                    continue;
                }
                if next=='u' {
                    // \u{...}
                    let mut j=i+2;
                    if j<n && chars[j]=='{' {
                        j+=1;
                        while j<n && chars[j]!='}' { j+=1; }
                        if j<n { j+=1; }
                        // Should be \u{xxx}
                        res.push_str(&s[i..j]);
                        i=j;
                        continue;
                    }
                }
                // Escaped special like \. etc, not colored specially? In earlier color for a.b, "\." was not colored specially, only ^$ etc? Let's check: for a.b with color, we had "a\.b" where "\." not colored? Actually earlier we had color for a.b: ^[1;33m^...a\.b...$ . So "\." not colored (no 103). So just copy.
                res.push('\\'); res.push(next);
                i+=2;
                continue;
            }
        }
        if chars[i]=='^' || chars[i]=='$' {
            res.push_str("\x1b[1;33m"); res.push(chars[i]); res.push_str("\x1b[0m");
            i+=1; continue;
        }
        if s[i..].starts_with("(?:") {
            res.push_str("\x1b[1;32m(?:\x1b[0m");
            i+=3; continue;
        }
        if chars[i]=='(' || chars[i]==')' {
            res.push_str("\x1b[1;32m"); res.push(chars[i]); res.push_str("\x1b[0m");
            i+=1; continue;
        }
        if chars[i]=='|' {
            res.push_str("\x1b[1;31m|\x1b[0m");
            i+=1; continue;
        }
        if chars[i]=='?' {
            res.push_str("\x1b[1;35m?\x1b[0m");
            i+=1; continue;
        }
        if chars[i]=='[' {
            res.push_str("\x1b[1;36m[\x1b[0m");
            in_class=true;
            i+=1; continue;
        }
        if chars[i]==']' {
            res.push_str("\x1b[1;36m]\x1b[0m");
            in_class=false;
            i+=1; continue;
        }
        if chars[i]=='-' && in_class {
            res.push_str("\x1b[1;36m-\x1b[0m");
            i+=1; continue;
        }
        if chars[i]=='{' {
            if let Some(end) = s[i..].find('}') {
                let token = &s[i..i+end+1];
                res.push_str("\x1b[104;37m"); res.push_str(token); res.push_str("\x1b[0m");
                i+= token.len();
                continue;
            }
        }
        // Handle (?x) etc
        if s[i..].starts_with("(?") {
            if let Some(end) = s[i..].find(')') {
                let token = &s[i..i+end+1];
                if token.contains('x') || token.contains('i') {
                    res.push_str("\x1b[40;93m"); res.push_str(token); res.push_str("\x1b[0m");
                    i+= token.len();
                    continue;
                }
            }
        }
        res.push(chars[i]);
        i+=1;
    }
    res
}

fn colorize_verbose_str(s: &str) -> String {
    // Apply colorize_token to each line but preserve indentation?
    // Actually we need to colorize tokens even with indentation.

