    // For our purposes, we will implement a method to collect all literal strings (original tokenized) that are in subtree of this node, up to a limit, and then find common suffix among them.

    // If common suffix found, we can factor.

    // Let's attempt to collect all strings in subtree (as joined token strings)

    fn collect_strings(node: &Node, prefix: Vec<String>, out: &mut Vec<Vec<String>>) {
        if node.is_end {
            out.push(prefix.clone());
        }
