use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::io::{self, Read};
use unicode_segmentation::UnicodeSegmentation;

fn parse_non_zero(s: &str) -> Result<u32, &'static str> {
    if s.is_empty() { return Err("invalid"); }
    if s.starts_with('-') { return Err("invalid"); }
    match s.parse::<u32>() {
        Ok(v) => { if v==0 { Err("zero") } else { Ok(v) } },
        Err(_) => Err("invalid"),
    }
}

