fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut has_help_long=false;
    let mut has_help_short=false;
    let mut has_ver=false;
    let mut seen_pos_for_help=false;
    let mut idx=1;
    while idx<args.len() {
        let arg=&args[idx];
        if arg=="--" { break; }
        if (arg=="--help" || arg=="-h" || arg=="--version" || arg=="-v") && !seen_pos_for_help {
            if arg=="--help" { has_help_long=true; } else if arg=="-h" { has_help_short=true; } else { has_ver=true; }
        }
        let is_bool = matches!(arg.as_str(), "-d" | "--digits" | "-D" | "--non-digits" | "-s" | "--spaces" | "-S" | "--non-spaces" | "-w" | "--words" | "-W" | "--non-words" | "-e" | "--escape" | "--with-surrogates" | "-r" | "--repetitions" | "--no-start-anchor" | "--no-end-anchor" | "--no-anchors" | "-x" | "--verbose" | "-c" | "--colorize" | "-i" | "--ignore-case" | "-g" | "--capture-groups" | "-h" | "--help" | "-v" | "--version");
        let is_val = matches!(arg.as_str(), "-f" | "--file" | "--min-repetitions" | "--min-substring-length");
        let is_val_eq = arg.starts_with("--file=") || arg.starts_with("--min-repetitions=") || arg.starts_with("--min-substring-length=");
        if is_bool { idx+=1; continue; }
        if is_val { idx+=2; continue; }
        if is_val_eq { idx+=1; continue; }
        seen_pos_for_help=true;
        break;
    }
    if has_help_long { print_long_help(); return; }
    if has_help_short { print_short_help(); return; }
    if has_ver { println!("grex 1.4.6"); return; }

    let mut file: Option<String>=None;
    let mut digits=false; let mut non_digits=false; let mut spaces=false; let mut non_spaces=false; let mut words=false; let mut non_words=false;
    let mut escape=false; let mut with_surrogates=false; let mut repetitions=false;
    let mut min_rep: u32=1; let mut min_sub_len: u32=1;
    let mut no_start=false; let mut no_end=false; let mut no_anchors=false;
    let mut verbose=false; let mut colorize=false; let mut ignore_case=false; let mut capture_groups=false;
    let mut inputs: Vec<String>=Vec::new();
    let mut i=1;
    let mut after_dd=false;
    let mut file_seen=false;
    let mut seen_first_pos=false;

    while i<args.len() {
        let arg = args[i].clone();
        if after_dd { inputs.push(arg); i+=1; continue; }
        if arg=="--" { after_dd=true; i+=1; continue; }
        if seen_first_pos { inputs.push(arg); i+=1; continue; }
        match arg.as_str() {
            "-d" | "--digits" => { digits=true; i+=1; continue; }
            "-D" | "--non-digits" => { non_digits=true; i+=1; continue; }
            "-s" | "--spaces" => { spaces=true; i+=1; continue; }
            "-S" | "--non-spaces" => { non_spaces=true; i+=1; continue; }
            "-w" | "--words" => { words=true; i+=1; continue; }
            "-W" | "--non-words" => { non_words=true; i+=1; continue; }
            "-e" | "--escape" => { escape=true; i+=1; continue; }
            "--with-surrogates" => { with_surrogates=true; i+=1; continue; }
            "-r" | "--repetitions" => { repetitions=true; i+=1; continue; }
            "--no-start-anchor" => { no_start=true; i+=1; continue; }
            "--no-end-anchor" => { no_end=true; i+=1; continue; }
            "--no-anchors" => { no_anchors=true; i+=1; continue; }
            "-x" | "--verbose" => { verbose=true; i+=1; continue; }
            "-c" | "--colorize" => { colorize=true; i+=1; continue; }
            "-i" | "--ignore-case" => { ignore_case=true; i+=1; continue; }
            "-g" | "--capture-groups" => { capture_groups=true; i+=1; continue; }
            _ => {}
        }
        if arg=="-f" || arg=="--file" {
            if file_seen { eprintln!("error: the argument '--file <FILE>' cannot be used multiple times\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'."); std::process::exit(2); }
            file_seen=true;
            if i+1>=args.len() { eprintln!("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            file=Some(args[i+1].clone()); i+=2; continue;
        }
        if arg.starts_with("--file=") {
            if file_seen { eprintln!("error: the argument '--file <FILE>' cannot be used multiple times\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'."); std::process::exit(2); }
            file_seen=true;
            let val=arg["--file=".len()..].to_string();
            if val.is_empty() { eprintln!("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            file=Some(val); i+=1; continue;
        }
        if arg=="--min-repetitions" {
            if i+1>=args.len() { eprintln!("error: a value is required for '--min-repetitions <QUANTITY>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            let vs=args[i+1].clone();
            match parse_non_zero(&vs) {
                Ok(v)=> min_rep=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-repetitions <QUANTITY>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=2; continue;
        }
        if arg.starts_with("--min-repetitions=") {
            let vs=arg["--min-repetitions=".len()..].to_string();
            match parse_non_zero(&vs) {
                Ok(v)=> min_rep=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-repetitions <QUANTITY>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=1; continue;
        }
        if arg=="--min-substring-length" {
            if i+1>=args.len() { eprintln!("error: a value is required for '--min-substring-length <LENGTH>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            let vs=args[i+1].clone();
            match parse_non_zero(&vs) {
                Ok(v)=> min_sub_len=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-substring-length <LENGTH>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-substring-length <LENGTH>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=2; continue;
        }
        if arg.starts_with("--min-substring-length=") {
            let vs=arg["--min-substring-length=".len()..].to_string();
            match parse_non_zero(&vs) {
                Ok(v)=> min_sub_len=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-substring-length <LENGTH>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-substring-length <LENGTH>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=1; continue;
        }
        seen_first_pos=true;
        inputs.push(arg);
        i+=1;
    }

    if file.is_some() && !inputs.is_empty() {
        eprintln!("error: the argument '--file <FILE>' cannot be used with '[INPUT]...'\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if file.is_none() && inputs.is_empty() {
        eprintln!("error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    let mut test_cases: Vec<String>=Vec::new();
    if let Some(f) = file {
        let path = if f=="-" {
            let mut buf=String::new();
            io::stdin().read_to_string(&mut buf).unwrap();
            let trimmed=buf.trim().to_string();
            if trimmed.is_empty() { eprintln!("error: the specified file could not be found"); std::process::exit(1); }
            trimmed
        } else { f };
        match fs::read_to_string(&path) {
            Ok(content) => {
                for line in content.split('\n') {
                    let l = if line.ends_with('\r') { line[..line.len()-1].to_string() } else { line.to_string() };
                    test_cases.push(l);
                }
            }
            Err(_) => { eprintln!("error: the specified file could not be found"); std::process::exit(1); }
        }
    } else {
        for inp in inputs {
            if inp=="-" {
                let mut buf=String::new();
                io::stdin().read_to_string(&mut buf).unwrap();
                for line in buf.split('\n') {
                    let l = if line.ends_with('\r') { line[..line.len()-1].to_string() } else { line.to_string() };
                    test_cases.push(l);
                }
            } else { test_cases.push(inp); }
        }
    }

    let mut set: BTreeSet<String> = BTreeSet::new();
    for tc in &test_cases { set.insert(tc.clone()); }
    let mut uniq: Vec<String> = set.into_iter().collect();
    let has_non_empty = uniq.iter().any(|s| !s.is_empty());
    if has_non_empty { uniq.retain(|s| !s.is_empty()); }
    if uniq.is_empty() {
        eprintln!("\nthread 'main' (1) panicked at /workspace/src/builder.rs:48:13:\nNo test cases have been provided for regular expression generation\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        std::process::exit(101);
    }

    let mut processed: Vec<String> = Vec::new();
    if ignore_case {
        let mut seen: BTreeSet<String> = BTreeSet::new();
        for s in uniq {
            let low = s.to_lowercase();
            if seen.insert(low.clone()) { processed.push(low); }
        }
    } else { processed = uniq; }

    let mut tokenized: Vec<Vec<String>> = Vec::new();
    for s in &processed {
        let conv = convert_string(s, digits, non_digits, spaces, non_spaces, words, non_words, escape, with_surrogates);
        let final_tokens = if repetitions {
            convert_rep_tokens(conv, min_sub_len as usize, min_rep as usize)
        } else { conv };
        tokenized.push(final_tokens);
    }

    let mut root = Node::new();
    for toks in &tokenized { root.insert(toks); }

    let base = gen_node(&root);
    let mut core = base.clone();
    if capture_groups { core = core.replace("(?:", "("); }

    if verbose {
        let mut out = String::new();
        if ignore_case { out.push_str("(?ix)\n"); } else { out.push_str("(?x)\n"); }
        if !no_anchors && !no_start { out.push_str("^\n"); }
        let body = format_verbose_body(&core);
        out.push_str(&body);
        if !out.ends_with('\n') { out.push('\n'); }
        if !no_anchors && !no_end { out.push_str("$\n"); }
        if colorize {
            print!("{}", colorize_verbose_str(&out));
        } else {
            print!("{}", out);
        }
    } else {
        let mut final_regex = String::new();
        if ignore_case { final_regex.push_str("(?i)"); }
        if !no_anchors && !no_start { final_regex.push('^'); }
        final_regex.push_str(&core);
        if !no_anchors && !no_end { final_regex.push('$'); }
        if colorize {
            println!("{}", colorize_token(&final_regex));
        } else {
            println!("{}", final_regex);
        }
    }
}
