                }
            } else { test_cases.push(inp); }
        }
    }

    let mut set: BTreeSet<String> = BTreeSet::new();
    for tc in &test_cases { set.insert(tc.clone()); }
    let mut uniq: Vec<String> = set.into_iter().collect();
    let has_non_empty = uniq.iter().any(|s| !s.is_empty());
    if has_non_empty { uniq.retain(|s| !s.is_empty()); }
