#[derive(Debug, Clone)]
struct Node {
    children: BTreeMap<String, Node>,
    is_end: bool,
}

impl Node {
    fn new() -> Self { Node { children: BTreeMap::new(), is_end: false } }
    fn insert(&mut self, tokens: &[String]) {
        if tokens.is_empty() { self.is_end=true; return; }
        let first=tokens[0].clone();
        let child=self.children.entry(first).or_insert_with(Node::new);
        child.insert(&tokens[1..]);
    }
    fn collect_strings(&self, prefix: Vec<String>, out: &mut Vec<Vec<String>>) {
        if self.is_end { out.push(prefix.clone()); }
        for (ch, child) in &self.children {
            let mut np=prefix.clone(); np.push(ch.clone());
            child.collect_strings(np, out);
        }
    }
}

fn is_digit_char(c: char) -> bool { c.is_digit(10) }
fn is_space_char(c: char) -> bool { c.is_whitespace() }
fn is_word_char(c: char) -> bool { c.is_alphanumeric() || c=='_' }

fn escape_literal_str(s: &str) -> String {
    if s.starts_with('\\') { return s.to_string(); }
    if s.contains('{') || s.contains('}') { return s.to_string(); }
    if s.starts_with("(?:") { return s.to_string(); }
    // also if it's like (ab) etc with parens, keep? For capture groups, it will be "(ab)" etc. We should keep as is if contains '(' and ')'
    if s.starts_with('(') && s.ends_with(')') && (s.contains('|') || s.len()>2) {
        return s.to_string();
    }
    let mut res=String::new();
    for g in s.graphemes(true) {
        if g.chars().count()==1 {
            let c=g.chars().next().unwrap();
            if ".^$*+?()[]{}|\\".contains(c) { res.push('\\'); res.push(c); } else { res.push_str(g); }
        } else { res.push_str(g); }
    }
    res
}

fn escape_inside_class(c: char) -> String {
    match c { '\\' | ']' | '[' | '^' | '-' => format!("\\{}", c), _ => c.to_string() }
}

fn build_char_class(chars: &[String]) -> (Option<String>, Vec<String>) {
    let mut single: Vec<char>=Vec::new();
    let mut multi: Vec<String>=Vec::new();
    for ch in chars {
        if ch.graphemes(true).count()==1 && ch.chars().count()==1 {
            single.push(ch.chars().next().unwrap());
        } else {
            if ch.chars().count()==1 {
                single.push(ch.chars().next().unwrap());
            } else {
                multi.push(ch.clone());
            }
        }
    }
    if single.is_empty() { return (None, multi); }
    // If only one char, don't create class, treat as literal? Actually for ["a","b"] we want class, for single char we don't.
    // We'll handle single length outside, but here we still create class for >=2
    if single.len() < 2 {
        return (None, chars.to_vec());
    }
    let mut set: BTreeSet<char>=BTreeSet::new();
    for c in single { set.insert(c); }
    let sorted: Vec<char>=set.into_iter().collect();
    let mut runs: Vec<Vec<char>>=Vec::new();
    let mut cur: Vec<char>=Vec::new();
    for &c in &sorted {
        if cur.is_empty() { cur.push(c); }
        else {
            if c as u32 == cur.last().unwrap().clone() as u32 + 1 { cur.push(c); }
            else { runs.push(cur); cur=vec![c]; }
        }
    }
    if !cur.is_empty() { runs.push(cur); }
    let mut content=String::new();
    for run in runs {
        if run.len()>=3 {
            content.push_str(&escape_inside_class(run[0]));
            content.push('-');
            content.push_str(&escape_inside_class(run[run.len()-1]));
        } else {
            for c in run { content.push_str(&escape_inside_class(c)); }
        }
    }
    (Some(format!("[{}]", content)), multi)
}

fn is_simple(s: &str) -> bool {
    if s.is_empty() { return true; }
    if s.contains('|') { return false; }
    if s.starts_with('(') { return false; }
    if s.contains('?') || s.contains('{') || s.contains('}') { return false; }
    if s.len()==1 { return true; }
    if s.starts_with('[') && s.ends_with(']') { return true; }
    if s.starts_with('\\') && s.len()==2 { return true; }
    if s.starts_with("\\u{") && s.ends_with('}') { return true; }
    false
}

fn make_optional(s: &str) -> String {
    if s.is_empty() { return "".to_string(); }
    if is_simple(s) { format!("{}?", s) } else { format!("(?:{})?", s) }
}

fn lcp_strs(a: &[String]) -> String {
    if a.is_empty() { return "".to_string(); }
    let mut pref=a[0].clone();
    for s in &a[1..] {
        let mut i=0;
        while i<pref.len() && i<s.len() && pref.as_bytes()[i]==s.as_bytes()[i] { i+=1; }
        pref=pref[..i].to_string();
        if pref.is_empty() { break; }
    }
    pref
}

fn lcs_strs(a: &[String]) -> String {
    if a.is_empty() { return "".to_string(); }
    let rev: Vec<String> = a.iter().map(|s| s.chars().rev().collect()).collect();
    let mut pref=rev[0].clone();
    for s in &rev[1..] {
        let mut i=0;
        let pc: Vec<char>=pref.chars().collect();
        let sc: Vec<char>=s.chars().collect();
        while i<pc.len() && i<sc.len() && pc[i]==sc[i] { i+=1; }
        pref=pc.iter().take(i).collect();
        if pref.is_empty() { break; }
    }
    pref.chars().rev().collect()
}

fn gen_node(node: &Node) -> String {
    if node.children.is_empty() {
        return "".to_string();
    }

    // Try common suffix
    let mut all_tokens: Vec<Vec<String>> = Vec::new();
    node.collect_strings(Vec::new(), &mut all_tokens);
    let all_joined: Vec<String> = all_tokens.iter().map(|t| t.join("")).collect();

    if all_joined.len() >= 2 {
        let cs = lcs_strs(&all_joined);
        if !cs.is_empty() && all_joined.iter().all(|s| s.ends_with(&cs)) && !all_joined.iter().all(|s| s == &cs) {
            let mut new_root = Node::new();
            let mut ok = true;
            for tokens in &all_tokens {
                let mut found = false;
                for cut in (0..=tokens.len()).rev() {
                    let suffix: String = tokens[cut..].join("");
                    if suffix == cs {
                        new_root.insert(&tokens[..cut]);
                        found = true;
                        break;
                    }
                }
                if !found { ok = false; break; }
            }
            if ok {
                let inner = gen_node(&new_root);
                return format!("{}{}", inner, cs);
            }
        }
    }

    let mut suffix_to_first: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (first, child) in &node.children {
        let suffix = gen_node(child);
        suffix_to_first.entry(suffix).or_default().push(first.clone());
    }
    let mut merged: Vec<String> = Vec::new();
    for (suffix, first_chars) in suffix_to_first.iter() {
        if first_chars.len() > 1 {
            // Separate escaping tokens vs literal
            let mut literal_chars: Vec<String> = Vec::new();
            let mut escape_tokens: Vec<String> = Vec::new();
            for fc in first_chars {
                if fc.starts_with('\\') || fc.contains('{') {
                    escape_tokens.push(fc.clone());
                } else {
                    literal_chars.push(fc.clone());
                }
            }
            if literal_chars.len() == 1 {
                merged.push(format!("{}{}", escape_literal_str(&literal_chars[0]), suffix));
            } else if literal_chars.len() > 1 {
                let (cc_opt, multi) = build_char_class(&literal_chars);
                if let Some(cc) = cc_opt {
                    merged.push(format!("{}{}", cc, suffix));
                    for m in multi { merged.push(format!("{}{}", escape_literal_str(m), suffix)); }
                } else {
                    for fc in &literal_chars {
                        merged.push(format!("{}{}", escape_literal_str(fc), suffix));
                    }
                }
            }
            for et in escape_tokens {
                merged.push(format!("{}{}", et, suffix));
            }
        } else {
            let fc = &first_chars[0];
            merged.push(format!("{}{}", escape_literal_str(fc), suffix));
        }
    }

    if node.is_end {
        if merged.is_empty() { return "".to_string(); }
        if merged.len() == 1 {
            return make_optional(&merged[0]);
        } else {
            let has_simple = merged.iter().any(|b| is_simple(b));
            if has_simple {
                let mut new_merged: Vec<String> = Vec::new();
                let mut used = false;
                for b in merged {
                    if !used && is_simple(&b) {
                        new_merged.push(format!("{}?", b));
                        used = true;
                    } else { new_merged.push(b); }
                }
                let mut sorted = new_merged.clone();
                sorted.sort_by(|a,b| { let o = b.len().cmp(&a.len()); if o!=std::cmp::Ordering::Equal { o } else { a.cmp(b) } });
                let inner = sorted.join("|");
                return format!("(?:{})", inner);
            } else {
                let mut sorted = merged.clone();
                sorted.sort_by(|a,b| { let o = b.len().cmp(&a.len()); if o!=std::cmp::Ordering::Equal { o } else { a.cmp(b) } });
                let inner = sorted.join("|");
                return format!("(?:{})?", inner);
            }
        }
    } else {
        if merged.len() == 1 { return merged[0].clone(); }
        let mut sorted = merged.clone();
        sorted.sort_by(|a,b| { let o = b.len().cmp(&a.len()); if o!=std::cmp::Ordering::Equal { o } else { a.cmp(b) } });
        let inner = sorted.join("|");
        return format!("(?:{})", inner);
    }
}

fn convert_char(c: char, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> String {
    let is_d = is_digit_char(c);
    let is_w = is_word_char(c);
    let is_s = is_space_char(c);
    if spaces && is_s { return "\\s".to_string(); }
    if digits && is_d { return "\\d".to_string(); }
    if words && is_w { return "\\w".to_string(); }
    if non_digits && !is_d { return "\\D".to_string(); }
    if non_words && !is_w { return "\\W".to_string(); }
    if non_spaces && !is_s { return "\\S".to_string(); }
    if ".^$*+?()[]{}|\\".contains(c) { format!("\\{}", c) } else { c.to_string() }
}

fn convert_string(s: &str, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool, escape: bool, with_surrogates: bool) -> Vec<String> {
    let mut tokens: Vec<String> = Vec::new();
    for c in s.chars() {
        if escape && !c.is_ascii() {
            let cp = c as u32;
            if with_surrogates && cp>=0x10000 {
                let cp_prime = cp-0x10000;
                let high = 0xD800 + ((cp_prime>>10)&0x3FF);
                let low = 0xDC00 + (cp_prime & 0x3FF);
                tokens.push(format!("\\u{{{:x}}}", high));
                tokens.push(format!("\\u{{{:x}}}", low));
            } else {
                tokens.push(format!("\\u{{{:x}}}", cp));
            }
        } else {
            tokens.push(convert_char(c, digits, non_digits, spaces, non_spaces, words, non_words));
        }
    }
    tokens
}

fn find_rep_tokens(tokens: &[String], min_sub_len: usize, min_rep: usize) -> Option<(usize, usize, usize)> {
    let n = tokens.len();
    if n==0 { return None; }
    let mut cands: Vec<(usize,usize,usize)> = Vec::new();
    for start in 0..n {
        for l in min_sub_len..=n {
            if start + l > n { break; }
            if start + l * (min_rep+1) > n { continue; }
            let mut cnt=1;
            let mut pos=start+l;
            while pos + l <= n {
                if tokens[start..start+l]==tokens[pos..pos+l] { cnt+=1; pos+=l; } else { break; }
            }
            if cnt >= min_rep+1 { cands.push((start,l,cnt)); }
        }
    }
    if cands.is_empty() { return None; }
    let mut ending: Vec<_> = cands.iter().filter(|(st,l,c)| st + l*c == n).cloned().collect();
    if !ending.is_empty() {
        ending.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
        return Some(ending[0]);
    }
    cands.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    Some(cands[0])
}

fn convert_rep_tokens(tokens: Vec<String>, min_sub_len: usize, min_rep: usize) -> Vec<String> {
    fn rec(toks: Vec<String>, min_sub_len: usize, min_rep: usize) -> Vec<String> {
        if toks.is_empty() { return Vec::new(); }
        if let Some((start,l,cnt)) = find_rep_tokens(&toks, min_sub_len, min_rep) {
            if start>0 {
                let prefix = toks[..start].to_vec();
                let conv_prefix = rec(prefix, min_sub_len, min_rep);
                let sub = toks[start..start+l].join("");
                let rep = if l==1 { format!("{}{{{}}}", sub, cnt) } else { format!("(?:{}){{{}}}", sub, cnt) };
                let suffix = toks[start+l*cnt..].to_vec();
                let conv_suffix = rec(suffix, min_sub_len, min_rep);
                let mut res = conv_prefix;
                res.push(rep);
                res.extend(conv_suffix);
                res
            } else {
                let sub = toks[..l].join("");
                let rep = if l==1 { format!("{}{{{}}}", sub, cnt) } else { format!("(?:{}){{{}}}", sub, cnt) };
                let suffix = toks[l*cnt..].to_vec();
                let conv_suffix = rec(suffix, min_sub_len, min_rep);
                let mut res = vec![rep];
                res.extend(conv_suffix);
                res
            }
        } else {
            toks
        }
    }
    rec(tokens, min_sub_len, min_rep)
}

fn split_top_level(s: &str) -> Vec<String> {
    let mut res: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut depth=0; let mut in_class=false; let mut esc=false;
    for c in s.chars() {
        if esc { cur.push(c); esc=false; continue; }
        if c=='\\' { cur.push(c); esc=true; continue; }
        if c=='[' && !in_class { in_class=true; cur.push(c); continue; }
        if c==']' && in_class { in_class=false; cur.push(c); continue; }
        if in_class { cur.push(c); continue; }
        if c=='(' { depth+=1; cur.push(c); continue; }
        if c==')' { depth-=1; cur.push(c); continue; }
        if c=='|' && depth==0 { res.push(cur); cur=String::new(); continue; }
        cur.push(c);
    }
    res.push(cur);
    res
}

fn parse_group(s: &str) -> (String, String) {
    let mut inner=String::new(); let mut quant=String::new();
    if s.ends_with('?') {
        quant="?".to_string();
        let without = &s[..s.len()-1];
        if without.ends_with(')') {
            if without.starts_with("(?:") { inner=without[3..without.len()-1].to_string(); }
            else if without.starts_with('(') { inner=without[1..without.len()-1].to_string(); }
        }
    } else if let Some(close)=s.rfind('}') {
        if let Some(open)=s[..close].rfind('{') {
            if let Some(paren)=s[..open].rfind(')') {
                quant=s[open..=close].to_string();
                let without = &s[..paren+1];
                if without.starts_with("(?:") { inner=without[3..without.len()-1].to_string(); }
                else if without.starts_with('(') { inner=without[1..without.len()-1].to_string(); }
            } else {
                quant=s[open..=close].to_string();
                inner=s[..open].to_string();
            }
        }
    } else {
        if s.starts_with("(?:") && s.ends_with(')') { inner=s[3..s.len()-1].to_string(); }
        else if s.starts_with('(') && s.ends_with(')') { inner=s[1..s.len()-1].to_string(); }
    }
    (inner, quant)
}

fn format_sequence(s: &str, indent: usize) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i=0;
    let mut literal_buf = String::new();
    while i<n {
        if s[i..].starts_with("(?:") || chars[i]=='(' {
            if !literal_buf.is_empty() { lines.push(format!("{}{}", " ".repeat(indent), literal_buf)); literal_buf.clear(); }
            let start=i;
            let mut depth=0; let mut in_class=false; let mut esc=false; let mut j=i;
            while j<n {
                let c=chars[j];
                if esc { esc=false; j+=1; continue; }
                if c=='\\' { esc=true; j+=1; continue; }
                if c=='[' && !in_class { in_class=true; j+=1; continue; }
                if c==']' && in_class { in_class=false; j+=1; continue; }
                if in_class { j+=1; continue; }
                if c=='(' { depth+=1; }
                else if c==')' {
                    depth-=1;
                    if depth==0 {
                        j+=1;
                        if j<n && chars[j]=='?' { j+=1; }
                        else if j<n && chars[j]=='{' {
                            while j<n && chars[j]!='}' { j+=1; }
                            if j<n { j+=1; }
                        }
                        break;
                    }
                }
                j+=1;
            }
            let group_str=s[start..j].to_string();
            let (inner, quant)=parse_group(&group_str);
            if inner.contains('|') {
                lines.push(format!("{}(?:", " ".repeat(indent)));
                let branches=split_top_level(&inner);
                for (idx, br) in branches.iter().enumerate() {
                    if idx>0 { lines.push(format!("{}|", " ".repeat(indent+2))); }
                    let sub_lines=format_sequence(br, indent+2);
                    lines.extend(sub_lines);
                }
                lines.push(format!("{}{}){}", " ".repeat(indent), "", quant));
            } else {
                lines.push(format!("{}(?:", " ".repeat(indent)));
                let sub=format_sequence(&inner, indent+2);
                lines.extend(sub);
                lines.push(format!("{}{}){}", " ".repeat(indent), "", quant));
            }
            i=j; continue;
        } else if chars[i]=='[' {
            let start=i;
            let mut j=i+1; let mut esc=false;
            while j<n {
                let c=chars[j];
                if esc { esc=false; j+=1; continue; }
                if c=='\\' { esc=true; j+=1; continue; }
                if c==']' { j+=1; break; }
                j+=1;
            }
            if j<n && chars[j]=='?' { j+=1; }
            else if j<n && chars[j]=='{' {
                while j<n && chars[j]!='}' { j+=1; }
                if j<n { j+=1; }
            }
            let token=s[start..j].to_string();
            literal_buf.push_str(&token);
            i=j; continue;
        } else if chars[i]=='\\' {
            let start=i;
            let mut j=i+1;
            if j<n && chars[j]=='u' {
                j+=1;
                if j<n && chars[j]=='{' {
                    j+=1;
                    while j<n && chars[j]!='}' { j+=1; }
                    if j<n { j+=1; }
                }
            } else { j+=1; }
            if j<n && chars[j]=='?' { j+=1; }
            else if j<n && chars[j]=='{' {
                while j<n && chars[j]!='}' { j+=1; }
                if j<n { j+=1; }
            }
            let token=s[start..j].to_string();
            literal_buf.push_str(&token);
            i=j; continue;
        } else {
            let start=i;
            let mut j=i;
            while j<n {
                let c=chars[j];
                if c=='(' || c=='[' || c=='\\' { break; }
                j+=1;
            }
            let token=s[start..j].to_string();
            literal_buf.push_str(&token);
            i=j; continue;
        }
    }
    if !literal_buf.is_empty() {
        lines.push(format!("{}{}", " ".repeat(indent), literal_buf));
    }
    lines
}

fn format_verbose_body(s: &str) -> String {
    if s.is_empty() { return "".to_string(); }
    if !s.contains('(') && !s.contains('|') {
        return format!("  {}\n", s);
    }
    let lines=format_sequence(s, 2);
    lines.join("\n") + "\n"
}

fn colorize_token(s: &str) -> String {
    let mut res=String::new();
    let mut i=0;
    let n=s.len();
    let bytes=s.as_bytes();
    let mut in_class=false;
    while i<n {
        if i+2<=n && (s[i..].starts_with("\\d") || s[i..].starts_with("\\w") || s[i..].starts_with("\\s") || s[i..].starts_with("\\D") || s[i..].starts_with("\\W") || s[i..].starts_with("\\S")) {
            res.push_str("\x1b[103;30m");
            res.push_str(&s[i..i+2]);
            res.push_str("\x1b[0m");
            i+=2; continue;
        }
        if s[i..].starts_with("(?") {
            if let Some(end)=s[i..].find(')') {
                let token=&s[i..i+end+1];
                if token.contains('x') || token.contains('i') {
                    res.push_str("\x1b[40;93m"); res.push_str(token); res.push_str("\x1b[0m");
                    i+= token.len(); continue;
                }
            }
        }
        if s[i..].starts_with("(?:") {
            res.push_str("\x1b[1;32m(?:\x1b[0m");
            i+=3; continue;
        }
        if i<n && (bytes[i]==b'(' || bytes[i]==b')') {
            res.push_str("\x1b[1;32m"); res.push(bytes[i] as char); res.push_str("\x1b[0m");
            i+=1; continue;
        }
        if bytes[i]==b'|' {
            res.push_str("\x1b[1;31m|\x1b[0m");
            i+=1; continue;
        }
        if bytes[i]==b'?' {
            res.push_str("\x1b[1;35m?\x1b[0m");
            i+=1; continue;
        }
        if bytes[i]==b'^' || bytes[i]==b'$' {
            res.push_str("\x1b[1;33m"); res.push(bytes[i] as char); res.push_str("\x1b[0m");
            i+=1; continue;
        }
        if bytes[i]==b'[' {
            res.push_str("\x1b[1;36m[\x1b[0m");
            in_class=true;
            i+=1; continue;
        }
        if bytes[i]==b']' {
            res.push_str("\x1b[1;36m]\x1b[0m");
            in_class=false;
            i+=1; continue;
        }
        if bytes[i]==b'-' && in_class {
            res.push_str("\x1b[1;36m-\x1b[0m");
            i+=1; continue;
        }
        if bytes[i]==b'{' {
            if let Some(end)=s[i..].find('}') {
                let token=&s[i..i+end+1];
                res.push_str("\x1b[104;37m"); res.push_str(token); res.push_str("\x1b[0m");
                i+= token.len(); continue;
            }
        }
        let ch_len=s[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        res.push_str(&s[i..i+ch_len]);
        i+= ch_len;
    }
    res
}

fn colorize_verbose_str(s: &str) -> String {
    colorize_token(s)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut has_help_long=false;
    let mut has_help_short=false;
    let mut has_ver=false;
    let mut seen_pos_for_help=false;
    let mut idx=1;
    while idx<args.len() {
        let arg=&args[idx];
        if arg=="--" { break; }
        if (arg=="--help" || arg=="-h" || arg=="--version" || arg=="-v") && !seen_pos_for_help {
            if arg=="--help" { has_help_long=true; } else if arg=="-h" { has_help_short=true; } else { has_ver=true; }
        }
        let is_bool = matches!(arg.as_str(), "-d" | "--digits" | "-D" | "--non-digits" | "-s" | "--spaces" | "-S" | "--non-spaces" | "-w" | "--words" | "-W" | "--non-words" | "-e" | "--escape" | "--with-surrogates" | "-r" | "--repetitions" | "--no-start-anchor" | "--no-end-anchor" | "--no-anchors" | "-x" | "--verbose" | "-c" | "--colorize" | "-i" | "--ignore-case" | "-g" | "--capture-groups" | "-h" | "--help" | "-v" | "--version");
        let is_val = matches!(arg.as_str(), "-f" | "--file" | "--min-repetitions" | "--min-substring-length");
        let is_val_eq = arg.starts_with("--file=") || arg.starts_with("--min-repetitions=") || arg.starts_with("--min-substring-length=");
        if is_bool { idx+=1; continue; }
        if is_val { idx+=2; continue; }
        if is_val_eq { idx+=1; continue; }
        seen_pos_for_help=true;
        break;
    }
    if has_help_long { print_long_help(); return; }
    if has_help_short { print_short_help(); return; }
    if has_ver { println!("grex 1.4.6"); return; }

    let mut file: Option<String>=None;
    let mut digits=false; let mut non_digits=false; let mut spaces=false; let mut non_spaces=false; let mut words=false; let mut non_words=false;
    let mut escape=false; let mut with_surrogates=false; let mut repetitions=false;
    let mut min_rep: u32=1; let mut min_sub_len: u32=1;
    let mut no_start=false; let mut no_end=false; let mut no_anchors=false;
    let mut verbose=false; let mut colorize=false; let mut ignore_case=false; let mut capture_groups=false;
    let mut inputs: Vec<String>=Vec::new();
    let mut i=1;
    let mut after_dd=false;
    let mut file_seen=false;
    let mut seen_first_pos=false;

    while i<args.len() {
        let arg = args[i].clone();
        if after_dd { inputs.push(arg); i+=1; continue; }
        if arg=="--" { after_dd=true; i+=1; continue; }
        if seen_first_pos { inputs.push(arg); i+=1; continue; }
        match arg.as_str() {
            "-d" | "--digits" => { digits=true; i+=1; continue; }
            "-D" | "--non-digits" => { non_digits=true; i+=1; continue; }
            "-s" | "--spaces" => { spaces=true; i+=1; continue; }
            "-S" | "--non-spaces" => { non_spaces=true; i+=1; continue; }
            "-w" | "--words" => { words=true; i+=1; continue; }
            "-W" | "--non-words" => { non_words=true; i+=1; continue; }
            "-e" | "--escape" => { escape=true; i+=1; continue; }
            "--with-surrogates" => { with_surrogates=true; i+=1; continue; }
            "-r" | "--repetitions" => { repetitions=true; i+=1; continue; }
            "--no-start-anchor" => { no_start=true; i+=1; continue; }
            "--no-end-anchor" => { no_end=true; i+=1; continue; }
            "--no-anchors" => { no_anchors=true; i+=1; continue; }
            "-x" | "--verbose" => { verbose=true; i+=1; continue; }
            "-c" | "--colorize" => { colorize=true; i+=1; continue; }
            "-i" | "--ignore-case" => { ignore_case=true; i+=1; continue; }
            "-g" | "--capture-groups" => { capture_groups=true; i+=1; continue; }
            _ => {}
        }
        if arg=="-f" || arg=="--file" {
            if file_seen { eprintln!("error: the argument '--file <FILE>' cannot be used multiple times\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'."); std::process::exit(2); }
            file_seen=true;
            if i+1>=args.len() { eprintln!("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            file=Some(args[i+1].clone()); i+=2; continue;
        }
        if arg.starts_with("--file=") {
            if file_seen { eprintln!("error: the argument '--file <FILE>' cannot be used multiple times\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'."); std::process::exit(2); }
            file_seen=true;
            let val=arg["--file=".len()..].to_string();
            if val.is_empty() { eprintln!("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            file=Some(val); i+=1; continue;
        }
        if arg=="--min-repetitions" {
            if i+1>=args.len() { eprintln!("error: a value is required for '--min-repetitions <QUANTITY>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            let vs=args[i+1].clone();
            match parse_non_zero(&vs) {
                Ok(v)=> min_rep=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-repetitions <QUANTITY>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=2; continue;
        }
        if arg.starts_with("--min-repetitions=") {
            let vs=arg["--min-repetitions=".len()..].to_string();
            match parse_non_zero(&vs) {
                Ok(v)=> min_rep=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-repetitions <QUANTITY>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=1; continue;
        }
        if arg=="--min-substring-length" {
            if i+1>=args.len() { eprintln!("error: a value is required for '--min-substring-length <LENGTH>' but none was supplied\n\nFor more information, try '--help'."); std::process::exit(2); }
            let vs=args[i+1].clone();
            match parse_non_zero(&vs) {
                Ok(v)=> min_sub_len=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-substring-length <LENGTH>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-substring-length <LENGTH>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=2; continue;
        }
        if arg.starts_with("--min-substring-length=") {
            let vs=arg["--min-substring-length=".len()..].to_string();
            match parse_non_zero(&vs) {
                Ok(v)=> min_sub_len=v,
                Err(e)=> {
                    if e=="zero" { eprintln!("error: invalid value '0' for '--min-substring-length <LENGTH>': Value must not be zero\n\nFor more information, try '--help'."); }
                    else { eprintln!("error: invalid value '{}' for '--min-substring-length <LENGTH>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", vs); }
                    std::process::exit(2);
                }
            }
            i+=1; continue;
        }
        seen_first_pos=true;
        inputs.push(arg);
        i+=1;
    }

    if file.is_some() && !inputs.is_empty() {
        eprintln!("error: the argument '--file <FILE>' cannot be used with '[INPUT]...'\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if file.is_none() && inputs.is_empty() {
        eprintln!("error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    let mut test_cases: Vec<String>=Vec::new();
    if let Some(f) = file {
        let path = if f=="-" {
            let mut buf=String::new();
            io::stdin().read_to_string(&mut buf).unwrap();
            let trimmed=buf.trim().to_string();
            if trimmed.is_empty() { eprintln!("error: the specified file could not be found"); std::process::exit(1); }
            trimmed
        } else { f };
        match fs::read_to_string(&path) {
            Ok(content) => {
                for line in content.split('\n') {
                    let l = if line.ends_with('\r') { line[..line.len()-1].to_string() } else { line.to_string() };
                    test_cases.push(l);
                }
            }
            Err(_) => { eprintln!("error: the specified file could not be found"); std::process::exit(1); }
        }
    } else {
        for inp in inputs {
            if inp=="-" {
                let mut buf=String::new();
                io::stdin().read_to_string(&mut buf).unwrap();
                for line in buf.split('\n') {
                    let l = if line.ends_with('\r') { line[..line.len()-1].to_string() } else { line.to_string() };
                    test_cases.push(l);
                }
            } else { test_cases.push(inp); }
        }
    }

    let mut set: BTreeSet<String> = BTreeSet::new();
    for tc in &test_cases { set.insert(tc.clone()); }
    let mut uniq: Vec<String> = set.into_iter().collect();
    let has_non_empty = uniq.iter().any(|s| !s.is_empty());
    if has_non_empty { uniq.retain(|s| !s.is_empty()); }
    if uniq.is_empty() {
        eprintln!("\nthread 'main' (1) panicked at /workspace/src/builder.rs:48:13:\nNo test cases have been provided for regular expression generation\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        std::process::exit(101);
    }

    let mut processed: Vec<String> = Vec::new();
    if ignore_case {
        let mut seen: BTreeSet<String> = BTreeSet::new();
        for s in uniq {
            let low = s.to_lowercase();
            if seen.insert(low.clone()) { processed.push(low); }
        }
    } else { processed = uniq; }

    let mut tokenized: Vec<Vec<String>> = Vec::new();
    for s in &processed {
        let conv = convert_string(s, digits, non_digits, spaces, non_spaces, words, non_words, escape, with_surrogates);
        let final_tokens = if repetitions {
            convert_rep_tokens(conv, min_sub_len as usize, min_rep as usize)
        } else { conv };
        tokenized.push(final_tokens);
    }

    let mut root = Node::new();
    for toks in &tokenized { root.insert(toks); }

    let base = gen_node(&root);
    let mut core = base.clone();
    if capture_groups { core = core.replace("(?:", "("); }

    if verbose {
        let mut out = String::new();
        if ignore_case { out.push_str("(?ix)\n"); } else { out.push_str("(?x)\n"); }
        if !no_anchors && !no_start { out.push_str("^\n"); }
        let body = format_verbose_body(&core);
        out.push_str(&body);
        if !out.ends_with('\n') { out.push('\n'); }
        if !no_anchors && !no_end { out.push_str("$\n"); }
        if colorize {
            print!("{}", colorize_verbose_str(&out));
        } else {
            print!("{}", out);
        }
    } else {
        let mut final_regex = String::new();
        if ignore_case { final_regex.push_str("(?i)"); }
        if !no_anchors && !no_start { final_regex.push('^'); }
        final_regex.push_str(&core);
        if !no_anchors && !no_end { final_regex.push('$'); }
        if colorize {
            println!("{}", colorize_token(&final_regex));
        } else {
            println!("{}", final_regex);
        }
    }
}
