    let mut root=Node::new();
    root.insert(&vec!["a".to_string()]);
    root.insert(&vec!["a".to_string(),"a".to_string()]);
    root.insert(&vec!["a".to_string(),"a".to_string(),"a".to_string()]);
    let res=gen_node(&root);
    println!("result {}", res);
}
