    let mut processed: Vec<String> = Vec::new();
    if ignore_case {
        let mut seen: BTreeSet<String> = BTreeSet::new();
        for s in uniq {
            let low = s.to_lowercase();
            if seen.insert(low.clone()) { processed.push(low); }
        }
    } else { processed = uniq; }

